window.SHOWCASE = [{"id": "paint-engine-demo-20260924-1", "case_id": "paint-engine-demo-20260924", "title": "Brush strokes (offline demo)", "type": "image", "group": "demos", "src": "assets/cases/paint-engine-demo-20260924-1.png", "poster": "assets/cases/paint-engine-demo-20260924-1.preview.jpg", "width": 800, "height": 560, "duration": null, "prompt": "libmypaint 离线笔刷样张：圆笔、软笔、压力细线、同层涂抹与擦除。仅验证引擎，不是模型画质评测。", "orientation": "landscape"}, {"id": "pathtrace-engine-demo-20260924-1", "case_id": "pathtrace-engine-demo-20260924", "title": "Material study (offline demo) · output 1", "type": "image", "group": "demos", "src": "assets/cases/pathtrace-engine-demo-20260924-1.png", "poster": "assets/cases/pathtrace-engine-demo-20260924-1.preview.jpg", "width": 512, "height": 512, "duration": null, "prompt": "离线写实渲染验证：陶瓷碗、金属球、玻璃杯", "orientation": "square"}, {"id": "pathtrace-engine-demo-20260924-2", "case_id": "pathtrace-engine-demo-20260924", "title": "Material study (offline demo) · output 2", "type": "image", "group": "demos", "src": "assets/cases/pathtrace-engine-demo-20260924-2.png", "poster": "assets/cases/pathtrace-engine-demo-20260924-2.preview.jpg", "width": 512, "height": 512, "duration": null, "prompt": "离线写实渲染验证：陶瓷碗、金属球、玻璃杯", "orientation": "square"}, {"id": "web-20260921-123257-09e5da-1", "case_id": "web-20260921-123257-09e5da", "title": "Botanical portrait", "type": "image", "group": "illustrations", "src": "assets/cases/web-20260921-123257-09e5da-1.png", "poster": "assets/cases/web-20260921-123257-09e5da-1.preview.jpg", "width": 1024, "height": 576, "duration": null, "prompt": "A centered portrait illustration of a beautiful young woman surrounded by abundant flowers and botanical foliage. She has long, voluminous wavy dark brown hair parted in the middle, closed eyes with long eyelashes, delicate facial features, warm fair skin, soft peach-colored lips, and a calm, peaceful expression. Her head and shoulders emerge from a dense circular arrangement of wildflowers, roses, daisies, orange blossoms, cream-colored flowers, eucalyptus leaves, sage-green foliage, small berries, and delicate botanical branches. Warm earthy palette of burnt orange, peach, cream, muted green, teal, and brown. Elegant hand-drawn botanical illustration, refined digital painting, soft watercolor and gouache texture, subtle ink outlines, vintage editorial illustration style, highly detailed hair strands and flower petals, harmonious symmetrical composition, soft natural shading, clean white background, isolated subject, no text, no border, square composition.", "orientation": "landscape"}, {"id": "web-20260921-141513-789c9c-1", "case_id": "web-20260921-141513-789c9c", "title": "Floral portrait", "type": "image", "group": "illustrations", "src": "assets/cases/web-20260921-141513-789c9c-1.png", "poster": "assets/cases/web-20260921-141513-789c9c-1.preview.jpg", "width": 1024, "height": 576, "duration": null, "prompt": "Elegant botanical portrait of a serene young woman with closed eyes and long wavy dark-brown hair, surrounded by a lush circular wreath of orange, peach, cream and white flowers, roses, daisies, eucalyptus and sage-green leaves. Warm earthy color palette, delicate feminine features, peaceful expression, detailed botanical petals and foliage, hand-drawn digital illustration, watercolor and gouache texture, subtle ink outlines, vintage editorial style, soft shading, decorative floral emblem, centered symmetrical composition, isolated on a pure white background, highly detailed, clean and refined.", "orientation": "landscape"}, {"id": "web-20260921-144837-040d97-1", "case_id": "web-20260921-144837-040d97", "title": "Castle infographic", "type": "image", "group": "posters", "src": "assets/cases/web-20260921-144837-040d97-1.png", "poster": "assets/cases/web-20260921-144837-040d97-1.preview.jpg", "width": 1152, "height": 2048, "duration": null, "prompt": "A highly detailed historical architectural infographic poster of a medieval European stone castle, presented like an antique museum survey sheet or architectural documentation board. The composition is vertically oriented on warm ivory parchment paper with a thin beige double-line border.\n\nMain upper panel: a large three-quarter bird’s-eye axonometric illustration of a massive circular medieval fortress built on a rocky island, with thick stone curtain walls, cylindrical defensive towers, conical wooden roofs, narrow arched windows, a central keep, inner courtyard, gatehouse, and a long stone bridge leading to the entrance. Rendered with extremely fine pen-and-ink linework, subtle watercolor washes, graphite shading, and realistic architectural texture. Muted sepia, warm gray, beige, dusty brown, and pale olive tones.\n\nSmall numbered callouts with thin leader lines identify different architectural elements around the castle. Add a small north compass in the upper-right area.\n\nTop-left title block: an old heraldic crest / coat of arms, followed by a large Chinese title and smaller English subtitle such as “OLAVINLINNA CASTLE”, with several short paragraphs of historical notes beneath it.\n\nRight-side information column: multiple neatly boxed technical panels containing construction date, architectural type, building materials, structural information, a simplified floor plan, a façade elevation diagram, and small section diagrams. Use thin technical drafting lines, numbered annotations, dimension labels, scale bars, and restrained Chinese typography.\n\nMiddle-left large panel: a frontal architectural elevation of the castle viewed from across the water, showing the bridge, rocky base, towers, gate, surrounding walls, and tiny human figures for scale. Add measurement guides, dashed construction lines, heights, widths, and scale notation.\n\nLower panels: an entrance circulation analysis diagram with directional arrows, a small aerial castle diagram, a material palette showing circular samples of stone, brick, timber, metal, and roof materials, detailed roof construction diagrams, arched window details, wall masonry details, and a vertical cutaway structural section through one tower showing timber floors, beams, roof trusses, stone walls, and foundation.\n\nOverall style: antique architectural encyclopedia, archaeological documentation, museum exhibition board, historical engineering drawing, architectural field survey, hand-rendered technical illustration, ink and watercolor on aged paper, Renaissance architectural sketchbook combined with modern infographic layout, precise and scholarly, elegant and restrained, extremely detailed, clean grid-based composition, no bright colors, no modern objects, no photorealistic rendering.", "orientation": "portrait"}, {"id": "web-20260921-150848-92d76b-1", "case_id": "web-20260921-150848-92d76b", "title": "Research framework", "type": "image", "group": "posters", "src": "assets/cases/web-20260921-150848-92d76b-1.png", "poster": "assets/cases/web-20260921-150848-92d76b-1.preview.jpg", "width": 2048, "height": 1152, "duration": null, "prompt": "A clean academic research framework diagram for a computer vision / generative AI paper, laid out horizontally from left to right in four major rounded rectangular panels, using a light blue and white color palette, thin blue-gray outlines, soft pastel section headers, and minimalist scientific infographic styling.\n\nPanel 1 — Inputs: a narrow vertical panel titled “Inputs” with two stacked rounded boxes labeled “Reference images” and “Task descriptions”, separated by a large plus sign. A right-pointing arrow connects this panel to the next stage.\n\nPanel 2 — Construct & refine: a large central panel titled “Construct & refine”. At the top-left, show a stylized editable 3D scene containing a yellow off-road vehicle, several pine trees, rocks, a ground grid, and a small virtual camera with blue viewing rays. To the right, include the heading “Editable scene” followed by compact sublabels such as “Geometry · materials · transforms”, “Lighting · cameras”, and “State updates · control inputs”. Below, place two rounded action boxes, “Execute & render” and “Inspect & revise”, connected by a curved iterative arrow loop. Under them, add a thin dotted separator and the label “Agent-generated example”, with two landscape example images side by side: one snowy outdoor scene and one muddy construction / off-road scene.\n\nPanel 3 — Agent-made conditions: a vertical panel titled “Agent-made conditions”, containing several stacked rounded modules. The first module is “Prompt + shot plan” with smaller text “T2V / T2AV”. The second is “Image / video references” with small video thumbnails and labels “I2V / I2AV” and “V2V / V2AV”. The third is “Pose + hand references” with the subtitle “Appearance + aligned motion”. The fourth is “Multi-ref / multi-shot” with short supporting text about mixing image, video, pose and hand references. The fifth is “Ref-to-AV” with smaller descriptive text about video or audio-video output and editing. Use small technical icons, reference thumbnails, and subtle dotted motion arrows.\n\nPanel 4 — Generative model: a final large panel titled “LynnReal-Omni”. At the top, include two input modules: “Appearance reference” with a simple image icon, and “Rendered controls” with two image icons and a small caption “3D renders / game recordings”. Both point downward into a central rounded box labeled “Native reference interface” and “Shared multimodal DiT”. A large downward arrow leads to “Generated video”, represented by a filmstrip icon with a central play button.\n\nAcross the very bottom, place a long horizontal validation bar spanning nearly the full width, labeled “Validation: runtime behavior · geometric validity · visual fidelity”. On the far right of this bar, add a small gray note stating that the screenshot is an agent-generated example and diffusion video outputs are not shown.\n\nVisual style: academic CVPR / ICCV / NeurIPS paper figure, vector infographic, highly organized grid layout, rounded rectangles, thin technical arrows, consistent spacing, modern sans-serif typography, dark navy text, pale blue headers, white background, subtle blue-gray borders, no gradients, no decorative background, no 3D glossy effects, precise alignment, publication-ready, high information density, clean and professional, landscape aspect ratio around 2.8:1.", "orientation": "landscape"}, {"id": "web-20260921-151506-54aa1e-1", "case_id": "web-20260921-151506-54aa1e", "title": "Cartoon workspace", "type": "image", "group": "illustrations", "src": "assets/cases/web-20260921-151506-54aa1e-1.png", "poster": "assets/cases/web-20260921-151506-54aa1e-1.preview.jpg", "width": 2048, "height": 2048, "duration": null, "prompt": "A cheerful cartoon-style young businessman sitting behind a wooden office desk, working with a silver laptop. He wears a dark blue business suit, white shirt, and red-brown tie. He has exaggerated large round eyes, thick dark brown swept-up hair, large ears, a wide open smile with white teeth, and a friendly enthusiastic expression. His left hand rests on a yellow folder on the desk, while his right hand is raised and pointing upward.\n\nAround his head, several floating office documents and reports form a circular workflow: sheets containing colorful pie charts, bar charts, dashboards, and simple analytics graphics, along with a green notebook. Large curved blue arrows connect the floating documents, creating a visual sense of iteration, document processing, data analysis, and workflow automation.\n\nOn the desk are a dark pencil holder filled with colorful pens and pencils, several small paper notes, a yellow folder, and an open gray laptop. The man sits in a dark office chair behind the desk.\n\nVisual style: clean flat vector illustration, playful corporate cartoon, polished 2D digital art, smooth rounded shapes, thick but soft outlines, subtle gradients and soft shading, bright pastel colors, friendly educational infographic style, exaggerated character proportions, large head and expressive facial features, simple geometric forms, clean white background, isolated composition, centered subject, high visual clarity, no complex background, no text, square image.", "orientation": "square"}, {"id": "web-20260921-152200-f1ebaa-1", "case_id": "web-20260921-152200-f1ebaa", "title": "Character ensemble", "type": "image", "group": "illustrations", "src": "assets/cases/web-20260921-152200-f1ebaa-1.png", "poster": "assets/cases/web-20260921-152200-f1ebaa-1.preview.jpg", "width": 2048, "height": 1152, "duration": null, "prompt": "A cheerful group portrait of eleven anthropomorphic cartoon dogs of different breeds, arranged in two rows against a clean white background. Each dog has a unique personality, body shape, facial expression, and color palette, but all share a consistent children’s animation style.\n\nBack row: a friendly gray-and-white husky with pointed ears and an excited expression; a tall brown dachshund wearing a green-and-yellow baseball cap and dark sunglasses, looking cool and confident; a slim brown-and-white Jack Russell terrier with wide curious eyes; a chubby beige pug with a wrinkled face, dark muzzle, and tongue sticking out; and a tall white Dalmatian with black spots and a slightly surprised expression.\n\nFront row: a stocky brown-and-white English bulldog with a serious grumpy face; a small orange-and-white corgi with large upright ears and an enthusiastic smile; a blue cartoon cattle dog standing upright with folded arms and a playful confident expression; a pink fluffy poodle with curly fur, blue bows on both ears, standing upright with hands on hips; a reddish-brown fox-like dog with pointed ears and a sarcastic half-lidded expression; a small light-blue puppy sitting upright; and a dark-blue floppy-eared hound sitting calmly with a relaxed smile.\n\nThe characters overlap slightly but remain clearly readable, forming a balanced ensemble cast. Their proportions are simplified and stylized, with large expressive eyes, oversized heads, short limbs, rounded paws, clean silhouettes, and exaggerated facial expressions.\n\nVisual style: polished 2D cartoon animation, children’s TV series character design, clean vector-like outlines, bold black contour lines, flat colors with minimal cel shading, soft rounded geometric shapes, expressive faces, playful family-friendly mood, crisp digital illustration, consistent line weight, high saturation but harmonious palette, no background scenery, pure white background, full-body character lineup, centered composition, high resolution.", "orientation": "landscape"}, {"id": "web-20260921-192338-06e89a-1", "case_id": "web-20260921-192338-06e89a", "title": "Chromatic sunset", "type": "video", "group": "videos", "src": "assets/cases/web-20260921-192338-06e89a-1.mp4", "poster": "assets/cases/web-20260921-192338-06e89a-1.preview.jpg", "width": 1280, "height": 720, "duration": 10.0, "prompt": "A surreal psychedelic sunset landscape in a vertical 9:16 composition. A massive dark tree dominates the left foreground, with a thick nearly black trunk and a dense canopy of deep purple, magenta and crimson leaves extending across the upper-left part of the frame.\n\nIn the center of the distant horizon, a brilliant glowing golden-yellow sun is setting between layered mountains. The distant mountains are painted in cool turquoise, teal and deep cyan tones, creating a strong contrast with the surrounding warm landscape.\n\nThe valley below is covered by an extremely vivid autumn forest filled with saturated red, orange, scarlet and crimson trees. The hills gradually recede toward the glowing sunset, creating strong atmospheric depth and a centered perspective.\n\nA winding river begins in the distant valley and snakes toward the bottom foreground. Instead of ordinary water, the river is filled with flowing psychedelic liquid-marble patterns. Dense ribbons of neon purple, magenta, cyan, turquoise, cobalt blue, yellow, orange, red and white swirl together like molten paint, acrylic pouring, oil marbling and liquid silk. The colored bands follow the curves of the river, continuously twisting, stretching and folding into one another.\n\nThe entire sky is transformed into an enormous psychedelic fluid painting. Swirling ribbons of violet, hot pink, turquoise, cyan, yellow, orange and fiery red replace ordinary clouds. The sky contains elongated flowing curves, vortex shapes, flame-like spirals and marbled waves, resembling a fusion of Van Gogh's swirling sky, liquid acrylic paint and psychedelic generative art.\n\nExtremely saturated colors, deep blacks, strong complementary color contrast, luminous neon highlights, intricate marbling, hypnotic flowing patterns, highly detailed surreal landscape, dreamlike atmosphere, psychedelic fantasy art, glowing sunset, rich texture, vivid autumn scenery.\n\nThe camera remains almost completely locked off. Preserve the composition, tree silhouette, mountains, sun and landscape structure throughout the entire shot. Animate only the colorful liquid textures: the sky slowly swirls and morphs, the river's marbled colors gently flow downstream, colored ribbons curl, stretch, merge and separate continuously. Very subtle motion in the foliage. Smooth slow organic movement, no sudden deformation, no scene changes, no camera cuts, no fast zoom, no camera shake.\n\n10-second seamless looping animation, hypnotic and continuous motion.", "orientation": "landscape"}, {"id": "web-20260921-233735-d9c9eb-1", "case_id": "web-20260921-233735-d9c9eb", "title": "Geometric composition", "type": "image", "group": "posters", "src": "assets/cases/web-20260921-233735-d9c9eb-1.png", "poster": "assets/cases/web-20260921-233735-d9c9eb-1.preview.jpg", "width": 2048, "height": 1152, "duration": null, "prompt": "A retro geometric abstract illustration composed of many colorful 3D isometric blocks and prisms, arranged inside a rectangular black grid like a patchwork poster. Each compartment contains a different simple geometric solid — cubes, rectangular cuboids, elongated prisms, diamond-shaped columns, and faceted blocks — rendered with flat shaded faces in contrasting colors such as teal blue, mustard yellow, magenta, brick red, forest green, orange, purple, and dark navy. The shapes use simplified isometric perspective with no outlines on individual faces, creating a playful optical-illusion effect. Each grid cell has a bold saturated background color, including red, yellow, blue, green, burgundy, and muted cyan. Thick black divider lines separate the panels. Vintage mid-century graphic design aesthetic, Bauhaus-inspired geometry, slightly muted screen-printed colors, subtle paper texture, imperfect analog print feel, clean composition, flat vector illustration, off-white outer background, no text.", "orientation": "landscape"}, {"id": "web-20260922-015242-53c0e0-1", "case_id": "web-20260922-015242-53c0e0", "title": "Shanghai city walk", "type": "image", "group": "posters", "src": "assets/cases/web-20260922-015242-53c0e0-1.png", "poster": "assets/cases/web-20260922-015242-53c0e0-1.preview.jpg", "width": 2048, "height": 1152, "duration": null, "prompt": "这是一张上海城市漫游主题拼贴海报，画面融合了东方明珠广播电视塔、外滩和平饭店、上海中心大厦、武康大楼等上海标志性地标建筑，并将这些建筑进行完整拼贴展示。文字部分包含醒目的中文主标题「上海城市漫游」、英文「ShanghaiCityWander」，以及顶部小字「Citywalk」rShang-haiLujiazui The Bund」，底部还有「随心」「热爱¥「漫无目的」「外滩」「陆家嘴」「摩登」等生活态度与城市记忆关键词及对应英文。整体采用复古拼贴风+酸性设计+蒸汽波风格，以藏蓝色半色调网点纹理为底，叠加鎏金暖橙不规则撕裂色块(适配上海海派摩登与老月份牌的复古质感)，建筑照片带有老上海胶片质感的做旧颗粒与轻微褪色感，文字错落拼贴排布，营造出90年代海派复古印刷品的视觉氛围，传递自由、随性、沉浸于上海摩登都市与烟火旧时光交织的城市漫步情绪。", "orientation": "landscape"}, {"id": "web-20260922-021138-b08d61-1", "case_id": "web-20260922-021138-b08d61", "title": "Annotated dining scene", "type": "image", "group": "editing", "src": "assets/cases/web-20260922-021138-b08d61-1.png", "poster": "assets/cases/web-20260922-021138-b08d61-1.preview.jpg", "width": 2048, "height": 1152, "duration": null, "prompt": "在每个盘子的周围画一个圈，这些圈的颜色各不相同，彩虹色", "orientation": "landscape"}, {"id": "web-20260922-103133-ed5f5f-1", "case_id": "web-20260922-103133-ed5f5f", "title": "Midnight laundry", "type": "video", "group": "videos", "src": "assets/cases/web-20260922-103133-ed5f5f-1.mp4", "poster": "assets/cases/web-20260922-103133-ed5f5f-1.preview.jpg", "width": 1280, "height": 720, "duration": 10.0, "prompt": "Build \"Midnight Laundry Portal\": a 10-second perfectly looping animated short made entirely with JavaScript and Canvas 2D. No audio. No images. No external assets. The story must read instantly on a phone screen with no explanation.\n\nStory\n\nA tiny laundromat sits empty at midnight. Three pastel washing machines sleep with closed ‿ eyes. A single red sock lies forgotten on a bench.\n\n0.0–1.5 s: fluorescent lights flicker awake one by one. The red sock slowly lifts its head as if alive.\n1.5–3.0 s: it hops toward the center washing machine. The circular door opens by itself, revealing not darkness but a tiny rotating starry galaxy.\n3.0–5.0 s: the sock leans in. Constellations, tiny planets, and glowing laundry symbols orbit inside the drum.\n5.0–7.0 s: the galaxy suddenly sucks the sock inside. The washer stretches like rubber, spins once, then spits out two matching red socks wearing miniature astronaut helmets.\n7.0–8.5 s: both socks proudly salute. A handwritten comic caption appears: \"MATCH FOUND!\"\n8.5–10.0 s: one sock trips backward into the washer, the galaxy collapses, lights switch off from right to left, returning exactly to the opening composition with one lonely sock on the bench.\nLook\n\nMaximum cozy midnight aesthetic: dusty lavender walls, mint-green washers, warm cream highlights, 5 px dark ink outlines, subtle paper grain, soft bloom, tiny dust particles, sleepy anthropomorphic machines, gentle squash-and-stretch.\n\nThe galaxy should contrast with the mundane laundromat: hand-drawn planets, orbit trails, stars, floating buttons and detergent bubbles.\n\nMotion\n\nUse slow anticipation followed by quick elastic actions. Every major object should have secondary motion: washer doors wobble, hanging clothes sway, detergent bottles bounce, ceiling lamps swing slightly.\n\nPerfect loop\n\nFrame 10.0 must visually match frame 0.0: one red sock, machines asleep, portal gone, lights dim.", "orientation": "landscape"}, {"id": "web-20260922-113627-3cadb1-1", "case_id": "web-20260922-113627-3cadb1", "title": "The tiny dragon barista", "type": "video", "group": "videos", "src": "assets/cases/web-20260922-113627-3cadb1-1.mp4", "poster": "assets/cases/web-20260922-113627-3cadb1-1.preview.jpg", "width": 1280, "height": 720, "duration": 10.0, "prompt": "Build \"The Tiny Dragon Barista\": a 10-second looping cozy fantasy animation, rendered entirely with JavaScript Canvas 2D. No sound, images, spritesheets, or video assets.\n\nStory\n\nA realistic-looking morning café counter is overlaid with playful hand-drawn fantasy elements. A coffee cup waits beneath an espresso machine. Sleeping inside the cup is a tiny orange dragon, curled like a cat.\n\n0.0–1.2 s: steam rises from the espresso machine and tickles the dragon's nose.\n1.2–2.5 s: the dragon sneezes a tiny puff of flame. Comic text: \"pff!\"\n2.5–4.0 s: the flame accidentally ignites three floating coffee beans, which become glowing fireflies.\n4.0–5.8 s: the dragon jumps onto the counter and chases them in a circular path around the cup, leaving a hand-drawn orange motion trail.\n5.8–7.2 s: it catches the final bean and breathes one controlled flame onto the coffee foam.\n7.2–8.5 s: the foam transforms into a perfect latte-art dragon face. The tiny dragon proudly places both hands on its hips.\n8.5–10.0 s: too much steam erupts; the dragon dives back into the cup, the foam collapses, and the original sleeping pose returns.\nLook\n\nCombine a semi-realistic café still-life composition with visibly illustrated overlays: inked flames, scribbled steam, glowing beans, exaggerated cartoon expressions.\n\nPalette: espresso brown, cream, muted sage, terracotta orange. Thick dark-brown outlines only on animated fantasy elements, while furniture and countertop use softer realistic shading.\n\nDetails\n\nAdd:\n\ncondensation on the ceramic cup,\ntiny crumbs moving when the dragon lands,\nhand-drawn spark symbols,\na hanging menu gently swaying,\nsteam morphing into temporary doodles: stars, hearts, spirals.\nLoop\n\nThe dragon must finish curled inside the cup in exactly the same pose as frame 0.", "orientation": "landscape"}, {"id": "web-20260922-120211-2f94e1-1", "case_id": "web-20260922-120211-2f94e1", "title": "Museum escape", "type": "video", "group": "videos", "src": "assets/cases/web-20260922-120211-2f94e1-1.mp4", "poster": "assets/cases/web-20260922-120211-2f94e1-1.preview.jpg", "width": 1280, "height": 720, "duration": 10.0, "prompt": "Build \"Museum Escape\": a 10-second silent looping animation where a hand-drawn character escapes from a framed painting into a realistic museum gallery. Render everything procedurally with JavaScript Canvas 2D.\n\nStory\n\nA quiet museum wall holds an ornate painting of a simple black-ink stick-figure knight standing inside a painted medieval landscape.\n\n0.0–1.3 s: the museum is still. The knight secretly looks left, then right.\n1.3–2.6 s: it pushes against the inside edge of the picture frame. The canvas stretches outward like rubber.\n2.6–4.0 s: the knight pops completely out of the painting, becoming a 2D doodle walking across the realistic museum wall.\n4.0–5.5 s: it steals a red apple from a classical still-life painting next door. The apple crosses styles: realistic inside the painting, then becomes a simple red doodle outside.\n5.5–6.8 s: a painted guard from another portrait notices. Giant illustrated \"!\" appears above his head.\n6.8–8.2 s: the knight sprints back, dragging the apple, while doodled arrows and speed lines cover the realistic gallery.\n8.2–9.2 s: it dives into its original painting. The frame ripples like water.\n9.2–10.0 s: everything becomes still again—except the knight now hides the tiny apple behind its back. It slowly moves the apple out of sight so the final frame matches the first.\nLook\n\nThe gallery should feel elegant and believable: cream walls, polished wooden floor, soft skylight, gold frames, realistic perspective.\n\nThe escaped knight remains visibly primitive:\nblack ink lines, intentionally imperfect joints, tiny dot eyes, exaggerated squash-and-stretch.\n\nThe strongest aesthetic contrast should be museum realism versus naive doodle animation.\n\nCamera\n\nUse one subtle push-in during the escape, then smoothly pull back to the exact original framing for the loop.", "orientation": "landscape"}, {"id": "web-20260922-130044-009c2b-1", "case_id": "web-20260922-130044-009c2b", "title": "A tower of moonlight", "type": "video", "group": "videos", "src": "assets/cases/web-20260922-130044-009c2b-1.mp4", "poster": "assets/cases/web-20260922-130044-009c2b-1.preview.jpg", "width": 1280, "height": 720, "duration": 5.0, "prompt": "A photorealistic desk lamp on a table, creatively reimagined as a giant moon observation tower. Tiny hand-drawn doodle cats climb the lamp stand like a spiral staircase, one cat peers through the lamp head as if it were a telescope, another cat hangs little star lanterns from the arm of the lamp. The lamp light becomes a glowing moonbeam, with doodled stars, clouds, and a small crescent moon surrounding it. Mixed-media style, realistic object combined with whimsical black-ink and pastel doodles, miniature fantasy world, playful and imaginative.", "orientation": "landscape"}, {"id": "web-20260922-130718-30ea7b-1", "case_id": "web-20260922-130718-30ea7b", "title": "Umbrella village", "type": "video", "group": "videos", "src": "assets/cases/web-20260922-130718-30ea7b-1.mp4", "poster": "assets/cases/web-20260922-130718-30ea7b-1.preview.jpg", "width": 1280, "height": 720, "duration": 5.0, "prompt": "A real open umbrella seen from the side, transformed into a floating hot-air-balloon village. The umbrella canopy becomes the balloon, while tiny hand-drawn doodle houses, flags, ropes, and ladders are attached underneath. Small doodle cats sit inside a hanging basket, one cat waves a flag, another cat pours tea. Around the umbrella float hand-drawn birds, clouds, wind swirls, and little suns. Photoreal everyday object mixed with sketchy doodle animation aesthetics, surreal yet cozy, full of childlike imagination.", "orientation": "landscape"}, {"id": "web-20260922-132631-86e6f8-1", "case_id": "web-20260922-132631-86e6f8", "title": "Pencil workshop", "type": "video", "group": "videos", "src": "assets/cases/web-20260922-132631-86e6f8-1.mp4", "poster": "assets/cases/web-20260922-132631-86e6f8-1.preview.jpg", "width": 1280, "height": 720, "duration": 5.0, "prompt": "A photoreal yellow pencil lies diagonally on a desk. At first it looks like an ordinary pencil, then tiny hand-drawn doodle cats rush in from off-screen carrying ropes, ladders, and toolboxes. They quickly build a launch platform around the pencil tip, transforming the pencil into a giant rocket. Doodled smoke, countdown signs, blinking lights, and scaffolding appear one by one. More tiny cats climb up and down the pencil body, preparing for takeoff. Suddenly the pencil-rocket trembles violently, the drawn flames burst out from the tip, clouds of doodled smoke expand across the desk, and the pencil launches upward with dramatic force, pulling a trail of sketchy fire and stars behind it. Small doodle objects scatter and spin through the air from the blast. The scene becomes a whimsical mixed-media launch sequence, with the real pencil remaining photorealistic and the fantasy world fully hand-drawn.", "orientation": "landscape"}, {"id": "web-20260922-133530-e957c6-1", "case_id": "web-20260922-133530-e957c6", "title": "Fan carnival", "type": "video", "group": "videos", "src": "assets/cases/web-20260922-133530-e957c6-1.mp4", "poster": "assets/cases/web-20260922-133530-e957c6-1.preview.jpg", "width": 1280, "height": 720, "duration": 5.0, "prompt": "A real tabletop electric fan sits quietly on a plain surface. Tiny doodle cats run into frame and begin attaching swings, hanging seats, flags, and carnival lights onto the fan blades and guard. As the doodled amusement park grows, more little cats jump aboard. The fan suddenly starts spinning slowly, then faster and faster. The doodle rides swing wildly outward under the strong rotation. Some cats are lifted into the air holding balloons, one nearly flies away, another grabs a rope and spins in a huge circle. Tickets, hats, popcorn, and banners burst loose and whirl around the fan in a chaotic spiral. Wind lines, swirling clouds, and motion marks fill the space. The spinning becomes a full-blown airborne carnival storm, combining a realistic fan with a lively hand-drawn micro-world full of energy, speed, and exaggerated motion.", "orientation": "landscape"}, {"id": "web-20260922-134656-5beed0-1", "case_id": "web-20260922-134656-5beed0", "title": "Suitcase station", "type": "video", "group": "videos", "src": "assets/cases/web-20260922-134656-5beed0-1.mp4", "poster": "assets/cases/web-20260922-134656-5beed0-1.preview.jpg", "width": 1280, "height": 720, "duration": 5.0, "prompt": "A closed photoreal suitcase rests on the floor. Tiny doodle cats appear and draw train tracks leading into the suitcase. They bang on the lid, place a station sign, and wave little flags. The suitcase suddenly pops open, and from inside bursts a miniature hand-drawn steam train at high speed. One train after another rushes out from the suitcase interior as if it contains an entire hidden railway world. Doodle passengers, luggage carts, smoke puffs, station lamps, and crossing gates rapidly appear around it. The tiny trains loop around the suitcase, race across the floor, dive into tunnels drawn in midair, and re-emerge from other sides. At the peak, a long train circles the suitcase in a sweeping curve while cats leap aboard, wave from windows, and throw luggage onto moving platforms. The real suitcase stays unchanged, but becomes the entrance to a wildly active doodle transportation world.", "orientation": "landscape"}, {"id": "web-20260922-142030-db30a3-1", "case_id": "web-20260922-142030-db30a3", "title": "Watering-can harbour", "type": "video", "group": "videos", "src": "assets/cases/web-20260922-142030-db30a3-1.mp4", "poster": "assets/cases/web-20260922-142030-db30a3-1.preview.jpg", "width": 1280, "height": 720, "duration": 5.0, "prompt": "A real metal watering can sits on a tabletop. Tiny doodle cats arrive carrying paddles, life rings, and signboards, then quickly draw channels, dams, and tiny docks around it. One cat turns the watering can, and a stream of water suddenly pours out. As the water flows, the drawn channels come alive, turning into a roaring doodle river. Little boats appear and launch into the current, carrying cats through sharp turns, splashes, and drops. The flow gets stronger and stronger, creating rapids, waterfalls, and spinning whirlpools made from hand-drawn lines and foam. More doodle fish leap out of the water, boats bounce upward, one cat nearly falls overboard, another surfs on a leaf racing downstream. The entire scene becomes a dramatic flood-powered amusement ride, mixing a real watering can with a vividly animated doodle whitewater world.", "orientation": "landscape"}, {"id": "web-20260922-144600-6fd0ea-1", "case_id": "web-20260922-144600-6fd0ea", "title": "A travelling town", "type": "video", "group": "videos", "src": "assets/cases/web-20260922-144600-6fd0ea-1.mp4", "poster": "assets/cases/web-20260922-144600-6fd0ea-1.preview.jpg", "width": 1280, "height": 720, "duration": 5.0, "prompt": "A photoreal scene with several real travel objects placed together: a pair of shoes, a hat, an umbrella, and a suitcase. Tiny hand-drawn doodle cats arrive and transform the setup into a bustling migration port. One shoe becomes a cargo boat, the other becomes a ferry dock, the umbrella opens into a giant airship terminal, the hat becomes a rounded hill village, and the suitcase opens into a customs station full of moving platforms. Tiny passengers pour out from the suitcase and split into multiple routes: some run toward the shoe-boats, others board dangling lifts that rise into the umbrella-airport, while a few climb to the hat village carrying flags and luggage. Doodled bridges, gangways, staircases, cranes, and flying signs rapidly appear between the objects. Then everything speeds up: the shoe-boat pulls away through drawn waves, the umbrella-airship lifts off with dangling ropes, luggage carts race between docking points, and a stream of cats runs across a narrow bridge just before it collapses and swings. The entire scene becomes a coordinated transport network spanning land, sea, and air, built from several ordinary real objects and brought to life with playful hand-drawn imagination.", "orientation": "landscape"}, {"id": "web-20260922-180106-dc78a7-1", "case_id": "web-20260922-180106-dc78a7", "title": "Festival illustration", "type": "image", "group": "illustrations", "src": "assets/cases/web-20260922-180106-dc78a7-1.png", "poster": "assets/cases/web-20260922-180106-dc78a7-1.preview.jpg", "width": 2048, "height": 1152, "duration": null, "prompt": "请模仿参考图像进行绘制，不可以使用image generation model", "orientation": "landscape"}, {"id": "web-20260922-191544-1b217f-1", "case_id": "web-20260922-191544-1b217f", "title": "Character portrait", "type": "image", "group": "illustrations", "src": "assets/cases/web-20260922-191544-1b217f-1.png", "poster": "assets/cases/web-20260922-191544-1b217f-1.preview.jpg", "width": 1556, "height": 1152, "duration": null, "prompt": "请根据参考图的内容，生成一样的头像内容", "orientation": "landscape"}, {"id": "web-20260922-194026-c49104-1", "case_id": "web-20260922-194026-c49104", "title": "Underwater cartoon", "type": "image", "group": "illustrations", "src": "assets/cases/web-20260922-194026-c49104-1.png", "poster": "assets/cases/web-20260922-194026-c49104-1.preview.jpg", "width": 2048, "height": 1152, "duration": null, "prompt": "[Identity]\nSpongeBob SquarePants, iconic yellow porous rectangular sponge body with irregular wavy edges, huge blue eyes, long nose, giant happy smile, two square front teeth, cheek freckles.\n\n[Pose]\nFull body, cheerful, both arms raised, playful welcoming pose, slightly bent leg, energetic and bouncy.\n\n[Outfit]\nWhite short-sleeve shirt, red tie, brown square pants, black belt detail, white socks with red and blue stripes, glossy black shoes.\n\n[Scene]\nBikini Bottom underwater setting, blue background, floating bubbles, sandy seabed, small sea plants and coral, pineapple house and Squidward stone house in the distance.\n\n[Style]\nClassic 2D cel-animation cartoon look, thick black outlines, flat saturated colors, minimal shading, faithful to the classic SpongeBob TV design.", "orientation": "landscape"}, {"id": "web-20260922-211408-e10827-1", "case_id": "web-20260922-211408-e10827", "title": "Pink character study", "type": "image", "group": "illustrations", "src": "assets/cases/web-20260922-211408-e10827-1.png", "poster": "assets/cases/web-20260922-211408-e10827-1.preview.jpg", "width": 2048, "height": 1152, "duration": null, "prompt": "请你模仿参考图像生成图像，如果执行步骤超过15轮就停止当前任务", "orientation": "landscape"}, {"id": "web-20260922-212741-1544c2-1", "case_id": "web-20260922-212741-1544c2", "title": "Forest characters", "type": "image", "group": "illustrations", "src": "assets/cases/web-20260922-212741-1544c2-1.png", "poster": "assets/cases/web-20260922-212741-1544c2-1.preview.jpg", "width": 2048, "height": 1152, "duration": null, "prompt": "请模仿输入的参考图绘制图像，如果执行轮数超过15轮，就停止当前任务", "orientation": "landscape"}, {"id": "web-20260922-213304-441e80-1", "case_id": "web-20260922-213304-441e80", "title": "Portrait cartoon", "type": "image", "group": "illustrations", "src": "assets/cases/web-20260922-213304-441e80-1.png", "poster": "assets/cases/web-20260922-213304-441e80-1.preview.jpg", "width": 1152, "height": 2048, "duration": null, "prompt": "请模仿输入的参考图绘制图像，如果执行轮数超过15轮，就停止当前任务", "orientation": "portrait"}, {"id": "web-20260922-215657-550647-1", "case_id": "web-20260922-215657-550647", "title": "Architectural poster", "type": "image", "group": "posters", "src": "assets/cases/web-20260922-215657-550647-1.png", "poster": "assets/cases/web-20260922-215657-550647-1.preview.jpg", "width": 1152, "height": 2048, "duration": null, "prompt": "请生成一张纵向建筑图鉴式信息海报，主题为“天安门广场”。整体风格参考复古建筑档案海报 / architectural atlas / 建筑图录页面：米白色旧纸背景，深棕色细线稿，低饱和暖色配色，版式克制、理性、优雅，带有建筑研究图板、博物馆展板、城市空间分析页的视觉气质。画面应适合程序化绘制，采用清晰分栏、模块化信息框、规则边线、细注释线和简洁矢量图形语言，适合 MaLiang Harness 通过 Canvas / SVG 生成。\n\n【核心目标】\n海报要以“天安门广场”的真实空间关系为基础，重点准确表达北京中轴线上天安门城楼与广场之间的空间序列。主建筑和广场布局要求真实、庄重、具有建筑可信度；周边信息模块采用图鉴和说明书式表达，不追求照片级复杂纹理，而追求清晰的结构表达与高辨识度。\n\n【整体构图】\n采用竖版海报，比例接近 A 系列纸张或 2:3。版面由四部分组成：\n1. 顶部标题区\n2. 中央主视觉建筑图\n3. 中下部的辅助分析图模块\n4. 底部的色彩、构件、信息说明模块\n\n整体留白充足，画面不拥挤，信息布局均衡。中央主图是视觉中心，其他内容围绕主图展开。\n\n【标题区】\n海报顶部设置建筑图录式标题排版：\n- 主标题为中文：“天安门广场”\n- 英文副标题：“Tiananmen Square”\n- 右上角可有小字信息，如“北京 · 中国 / BEIJING, CHINA”\n- 再加入简洁分类信息，如“城楼 / 广场 / 中轴秩序”\n- 整体字体观感应优雅、学术、图录化，不要现代商业广告风\n\n【中央主视觉】\n中央主图采用高质量轴测 / 等距 / 略俯视建筑插画方式，真实表现天安门广场的核心空间结构。重点是“真实空间关系”而不是卡通化表达。\n\n主视觉应包括以下建筑与空间元素，并强调它们的相对位置：\n\n1. 天安门城楼位于主图北端，为最重要主体：\n   - 红色城台与红墙\n   - 黄色琉璃瓦重檐歇山顶\n   - 白色汉白玉台基与栏杆\n   - 正立面应具有明显的五个门洞\n   - 上部城楼应体现传统宫殿式木构建筑的层次感\n   - 整体要有九开间宫殿建筑的感觉，比例庄重，对称明确\n   - 建筑风格真实，不做夸张卡通化处理\n   - 如果聚焦建筑图鉴，可省略正面画像和标语，避免破坏建筑研究海报的纯净性\n\n2. 天安门前方应有外金水桥与水系：\n   - 明确表现天安门前的护城河式水带\n   - 表现 7 座外金水桥，围绕中轴线对称分布\n   - 桥、栏杆、华表等元素需简洁但准确，作为传统礼制空间的前景过渡\n\n3. 广场空间要明显向南延展，不能压缩成短小前庭：\n   - 主图中必须拉开南北纵深，形成“城楼—桥群—广场”的长轴感\n   - 铺地采用规整浅色方格或石板纹理，强化开阔、秩序化的城市公共空间特征\n   - 中轴线应明确可见，贯穿城楼前方并延伸向南\n\n4. 中轴线上的关键纪念性要素：\n   - 北侧靠近广场前部的位置可设置国旗杆区域，但保持简洁\n   - 人民英雄纪念碑应位于广场中轴线上，并且明显比上一版更靠南，不能紧贴天安门\n   - 毛主席纪念堂应继续位于纪念碑南侧，也在中轴线上，构成完整的广场纵深序列\n   - 若空间允许，可在最南端以弱化方式提示正阳门 / 前门的位置，作为中轴序列终点的象征性标识\n\n5. 广场两侧的大体量建筑：\n   - 西侧为人民大会堂\n   - 东侧为中国国家博物馆\n   - 两者应以长条形、大尺度建筑体量围合广场，不应被画成过小的小盒子\n   - 可适度简化细节，但必须保留“东西对称、界定广场边界、体量显著”的特征\n   - 它们应远大于普通配楼，形成广场两侧的重要城市界面\n\n【主视觉风格要求】\n中央主图中的建筑必须写实建筑插画化：\n- 比例合理\n- 结构准确\n- 轮廓清楚\n- 材质色彩克制\n- 不要做照片拼贴\n- 不要做夸张宣传画\n- 不要出现拥挤人群、车辆和复杂事件叙事\n- 可带轻微模型感和说明图感，但不能玩具化\n\n【辅助分析模块】\n在中央主图下方与侧边布置若干建筑分析小模块，像建筑手册中的信息框。各模块用细线分隔，标题编号简洁统一，如 02, 03, 04 等。建议包括：\n\n1. 正立面图\n- 用简洁线稿展示天安门城楼正立面\n- 明确表现重檐屋顶、城台、五门洞\n- 保持建筑比例和中轴对称感\n\n2. 平面关系图\n- 用极简平面图形式表示天安门广场的空间布局\n- 北端标出天安门\n- 东侧标出中国国家博物馆\n- 西侧标出人民大会堂\n- 中轴线上依次标出国旗杆、人民英雄纪念碑、毛主席纪念堂\n- 如有余量，可在最南端弱化标注正阳门\n- 这是一个空间关系示意图，不只是抽象图标\n\n3. 屋顶与剖面\n- 用简洁剖面小图表现天安门城楼重檐歇山顶、柱网和台基关系\n- 体现传统中国宫殿建筑的层次感\n\n4. 构件细节\n- 小图标式表现汉白玉栏杆、金水桥、屋瓦、城台、券门、华表等要素\n- 保持建筑说明图风格，简洁精致\n\n5. 尺寸 / 比例\n- 用横向或竖向示意线表达天安门城楼的比例关系、台基高度、城楼高度感\n- 不要求所有数值严格精确，但要像专业建筑图录的尺寸信息框\n\n6. 基础信息\n- 可简要写：\n  - 始建：明永乐十五年（1417），初名承天门，后改称天安门\n  - 类型：城楼 / 城市广场 / 纪念性公共空间\n  - 特征：中轴对称、礼制秩序、开阔广场、传统与现代公共建筑并置\n- 文字不宜过长，保持简洁学术风格\n\n7. 色彩 / 材质\n- 以小圆点或小色块呈现典型材质与色彩：\n  - 朱红\n  - 琉璃金黄\n  - 汉白玉白\n  - 灰砖灰\n  - 浅石材米灰\n- 旁边配以一句简短说明，强调传统宫殿建筑与现代广场空间的综合色彩关系\n\n【色彩要求】\n整体主色控制为：\n- 米白旧纸背景\n- 深棕色线稿与标题\n- 朱红色用于天安门城台与墙体\n- 金黄色用于琉璃瓦顶\n- 浅灰白用于石质台基和栏杆\n- 浅青灰或浅灰用于铺地与辅助建筑\n整体低饱和、克制、有图录感，不要高饱和商业海报效果。\n\n【程序化 / Harness 友好要求】\n- 强调清晰几何轮廓和可拆解的结构表达\n- 主图与辅助图都应适合由矢量路径、矩形、折线、圆弧、多边形和文本框程序化生成\n- 小字说明不必非常密集，可少量真实文字 + 若干简洁标签\n- 排版结构应清晰稳定，避免过多随机装饰\n- 整体应像一张可由代码构建的“建筑研究海报”，而不是依赖复杂手绘肌理的插画\n\n【气质关键词】\n庄重、安静、学术、复古、建筑图鉴、说明书感、空间分析感、博物馆教育海报、城市中轴研究页、传统建筑与公共空间研究。\n\n【负面约束】\n不要卡通建筑，不要现代 UI 仪表盘风，不要赛博风，不要 3D 游戏截图风，不要宣传画风，不要人群密集场景，不要复杂交通流，不要夸张透视，不要把人民英雄纪念碑画得离天安门太近，不要遗漏毛主席纪念堂，不要把人民大会堂和中国国家博物馆缩得过小，不要把广场画成一个短小前院。", "orientation": "portrait"}, {"id": "web-20260923-113737-c9d224-1", "case_id": "web-20260923-113737-c9d224", "title": "Photographic editing study", "type": "image", "group": "editing", "src": "assets/cases/web-20260923-113737-c9d224-1.png", "poster": "assets/cases/web-20260923-113737-c9d224-1.preview.jpg", "width": 2048, "height": 1152, "duration": null, "prompt": "手表的大小与手腕不符合", "orientation": "landscape"}, {"id": "web-20260923-121103-c75c3b-1", "case_id": "web-20260923-121103-c75c3b", "title": "Product composition", "type": "image", "group": "editing", "src": "assets/cases/web-20260923-121103-c75c3b-1.png", "poster": "assets/cases/web-20260923-121103-c75c3b-1.preview.jpg", "width": 2048, "height": 1152, "duration": null, "prompt": "人物和产品的比例不对", "orientation": "landscape"}, {"id": "web-20260923-123404-7070a9-1", "case_id": "web-20260923-123404-7070a9", "title": "Fashion composition", "type": "image", "group": "editing", "src": "assets/cases/web-20260923-123404-7070a9-1.png", "poster": "assets/cases/web-20260923-123404-7070a9-1.preview.jpg", "width": 2048, "height": 1152, "duration": null, "prompt": "衣服的大小和人物比例不合适，同时背景太单调了", "orientation": "landscape"}, {"id": "web-20260923-124153-1f9c42-1", "case_id": "web-20260923-124153-1f9c42", "title": "Character background study", "type": "image", "group": "editing", "src": "assets/cases/web-20260923-124153-1f9c42-1.png", "poster": "assets/cases/web-20260923-124153-1f9c42-1.preview.jpg", "width": 2048, "height": 1152, "duration": null, "prompt": "请把背景颜色替换为彩色的", "orientation": "landscape"}, {"id": "web-20260923-130205-59081b-1", "case_id": "web-20260923-130205-59081b", "title": "Fashion infographic", "type": "image", "group": "posters", "src": "assets/cases/web-20260923-130205-59081b-1.png", "poster": "assets/cases/web-20260923-130205-59081b-1.preview.jpg", "width": 1152, "height": 2048, "duration": null, "prompt": "可以替换一个更加高级的背景颜色吗", "orientation": "portrait"}, {"id": "web-20260923-150321-09d321-1", "case_id": "web-20260923-150321-09d321", "title": "Research infographic (illustrative)", "type": "image", "group": "posters", "src": "assets/cases/web-20260923-150321-09d321-1.png", "poster": "assets/cases/web-20260923-150321-09d321-1.preview.jpg", "width": 2048, "height": 1152, "duration": null, "prompt": "制作一张计算机视觉与机器人学习论文中的综合研究结果图，主题为：\n\n“Visuo-Tactile Robot Manipulation”\n\n图中展示一个虚构的视觉—触觉机器人策略“VT-Policy”，说明机器人如何结合视觉、触觉和自身状态完成精细操作。\n\n这是一张科研论文多面板图，不是科普海报、宣传广告或软件界面。所有实验数值均为示意数据，必须在页面底部清晰标注：\n“Illustrative research figure — all numerical results are synthetic.”\n\n────────────────────────\n一、整体构图与视觉风格\n────────────────────────\n\n横版画布，3:2，建议3000×2000或更高分辨率。\n\n采用白色背景、细灰色分隔线、克制的浅色模块填充。文字为清晰的英文无衬线字体，标题略粗，正文和图例大小统一。不要使用巨大主标题，不要使用装饰性渐变、立体卡片、厚重阴影或背景纹理。\n\n整体划分为六个面板：\n\n上排：\n(a) 左侧约58%宽度：Overall Architecture\n(b) 右侧约42%宽度：Unseen-Object Generalization\n\n下排：\n(c) 左侧约35%宽度：Qualitative Results\n(d) 中间约30%宽度：Data Efficiency\n(e) 右侧约35%宽度的上半区：Ablation Study\n(f) 右侧约35%宽度的下半区：Contact-State Embedding\n\n上下两排高度接近，下排略高。各面板之间留出足够间距，禁止图例、文字或箭头跨入相邻面板。\n\n每个面板标题采用统一格式，例如：\n“(a) Overall Architecture”\n\n方法框图中的输入模态配色：\n视觉：柔和蓝色\n触觉：柔和绿色\n机器人状态：浅紫色\n\n统计图中的方法配色：\nVision Only：灰色\nLate Fusion：蓝色\nVT-Policy：珊瑚红色\n\n同一个方法在所有统计图中必须使用相同颜色。\n\n────────────────────────\n二、面板(a)：Overall Architecture\n────────────────────────\n\n绘制从左到右的机器人策略架构图。\n\n左侧并列排列三行输入：\n\n第一行：\n“RGB Observation”\n缩略图为真实摄影风格：桌面机械臂正在将USB插头对准接口，能够看见夹爪、插头和接口。\n\n第二行：\n“Tactile Observation”\n缩略图为两张并排的视觉式触觉传感器图像，分别对应左右夹指。图像中具有真实的接触压痕、细密纹理和接触区域变化，不要使用普通手指照片代替。\n\n第三行：\n“Robot State”\n以简洁的关节示意图和数值条表示机器人状态，不需要再放一张复杂照片。\n\n三行输入分别通过水平箭头进入：\n“Vision Encoder”\n“Tactile Encoder”\n“State Encoder”\n\n编码器右侧分别画出对应颜色的token小方块：\n视觉token为蓝色；\n触觉token为绿色；\n状态token为紫色。\n\n三组token共同连接到一个较大的浅蓝灰色模块：\n“Temporal Fusion Transformer”\n\n然后依次连接：\n“Action Decoder”\n→ “Action Chunk”\n→ “Robot Execution”\n\n“Action Chunk”下方使用较小文字注明：\n“End-effector pose + gripper”\n\n“Robot Execution”用一张小型真实机器人操作图或简洁机械臂示意图表示。\n\n从“Robot Execution”绘制一条沿框图下方返回输入观测端的反馈箭头，标注：\n“Closed-loop observations”\n\n在视觉和触觉编码器下方放置一个较小的虚线框：\n“Visual–Tactile Alignment”\n“Training only”\n\n从视觉与触觉编码表示分别引出细虚线连接到这个训练目标框。不要把训练目标画成推理时必须经过的主链路。\n\n逻辑必须明确：\n观测 → 编码 → 多模态时序融合 → 动作预测 → 机器人执行 → 新观测。\n\n不要沿用图像理解、文本生成、音频描述等任务头；这里的最终输出是机器人动作。\n\n────────────────────────\n三、面板(b)：Unseen-Object Generalization\n────────────────────────\n\n绘制规范的分组柱状图，比较三个方法在五类任务上的成功率。\n\n纵轴：\n“Success Rate (%)”\n范围固定为0–100，刻度为0、20、40、60、80、100。\n\n横轴任务：\nUSB Insertion\nFragile Grasp\nSurface Sorting\nGear Assembly\nDrawer Opening\n\n图例：\nVision Only\nLate Fusion\nVT-Policy\n\n使用以下精确示意数据：\n\nTask                Vision Only   Late Fusion   VT-Policy\nUSB Insertion       42            61            82\nFragile Grasp       61            76            89\nSurface Sorting     38            59            81\nGear Assembly       49            72            88\nDrawer Opening      75            84            89\n\n每个任务包含三根柱子，柱高必须与数值一致。\n柱顶用小字标注数值，不添加没有依据的误差棒、显著性星号或“SOTA”声明。\n\n长任务名可换为两行，不能挤在一起。\n坐标网格使用极淡灰色，不能盖过柱子。\n\n────────────────────────\n四、面板(c)：Qualitative Results\n────────────────────────\n\n绘制四行、三列的定性结果展示表。\n\n列标题：\n“Task”\n“Vision Only”\n“VT-Policy”\n\n四行任务：\nUSB Insertion\nFragile Grasp\nSurface Sorting\nGear Assembly\n\n每一行的两张结果图采用相同的机器人、桌面、物体、观察角度和光照，避免通过切换场景制造不公平的视觉差异。\n\n第一行：USB Insertion\nVision Only：插头与接口存在轻微横向偏移，尚未插入。\nVT-Policy：插头正确对齐并插入接口。\n短标签：\n“Misaligned”\n“Inserted”\n\n第二行：Fragile Grasp\nVision Only：薄脆饼干被夹爪压裂，可以看到少量碎片。\nVT-Policy：相同饼干被轻柔夹持，保持完整。\n短标签：\n“Cracked”\n“Intact”\n\n第三行：Surface Sorting\n场景中有两个外形和颜色接近、但表面粗糙程度不同的物体。\nVision Only：目标粗糙物体被放入标记为“Smooth”的分类区域。\nVT-Policy：目标粗糙物体被放入标记为“Rough”的分类区域。\n短标签：\n“Wrong bin”\n“Correct bin”\n\n第四行：Gear Assembly\nVision Only：齿轮倾斜地卡在轴上。\nVT-Policy：齿轮水平、完整地安装到轴上。\n短标签：\n“Jammed”\n“Seated”\n\n图片采用真实机器人实验摄影风格。\n允许使用细红框或细绿框标出关键接触区域，但不要覆盖操作对象。\n不要加入夸张表情、卡通机器人或复杂文字说明。\n\n这些图像是概念性的操作示例，不要伪装成带真实实验编号的采集记录。\n\n────────────────────────\n五、面板(d)：Data Efficiency\n────────────────────────\n\n绘制三条带圆形数据点的学习曲线。\n\n横轴：\n“Demonstrations per Task”\n刻度：\n20、40、60、80、100\n\n纵轴：\n“Average Success Rate (%)”\n范围固定为0–100。\n\n三条曲线的数据为：\n\nDemonstrations      20   40   60   80   100\nVision Only         24   35   42   48   53.0\nLate Fusion         33   47   58   65   70.4\nVT-Policy           44   62   74   81   85.8\n\n使用真实数值位置绘制圆点，再用清晰的线段连接。\n灰色对应Vision Only，蓝色对应Late Fusion，红色对应VT-Policy。\n\n在不遮挡曲线的位置添加一句小号红色注释：\n“Higher success with fewer demonstrations”\n\n图例放在空白区域，不要遮住任何数据点。\n\n100个示范时的三个终点必须分别为53.0、70.4和85.8，与面板(b)中五个任务的平均值一致。\n\n────────────────────────\n六、面板(e)：Ablation Study\n────────────────────────\n\n绘制一张简洁的论文风格表格，细线分隔，表头浅灰底。\n\n表格列为：\nVariant | USB | Fragile | Surface | Gear | Drawer | Avg.\n\n使用以下精确数据：\n\nVision Only       42   61   38   49   75   53.0\nLate Fusion       61   76   59   72   84   70.4\nw/o Temporal      73   84   74   80   86   79.4\nw/o Alignment     77   85   75   84   87   81.6\nFull Model        82   89   81   88   89   85.8\n\n“Full Model”对应VT-Policy。\n最后一行使用很浅的红色底纹，模型名称和平均值适度加粗。\n\n所有数值右对齐或按列居中，平均值保留一位小数。\n不要自动修改数据，不要使Avg.列与前面五列不一致。\n表格下方用小字注明：\n“Success rate (%); illustrative values.”\n\n────────────────────────\n七、面板(f)：Contact-State Embedding\n────────────────────────\n\n绘制一个二维特征分布示意图，用来表现不同模态对相同接触状态的对应关系。\n\n这是概念投影，不是实际计算得到的t-SNE或UMAP结果。\n在图内下方注明：\n“Schematic projection”\n\n使用三种颜色区分三个接触状态：\nStable Contact\nSlip\nInsertion Complete\n\n使用两种点形区分输入模态：\n圆点：Vision\n三角形：Touch\n\n画出三个松散分离的语义簇。\n每个簇内部都应同时包含相互混合的圆点和三角形，而不是让视觉与触觉形成两个完全分开的群体。\n\n每个簇外围可以绘制很淡的虚线轮廓。\n标签靠近对应簇，不能遮挡点云。\n模态图例仅解释圆点和三角形，保持简洁。\n\n坐标轴标注：\n“Component 1”\n“Component 2”\n\n不要使用没有实际定义的百分比或对齐分数。\n不要把不同模态完全分开的点云标为“Aligned”。\n\n────────────────────────\n八、素材与绘制要求\n────────────────────────\n\n采用“真实图像素材 + 程序化科研排版”的混合方式制作：\n\n机器人、桌面、操作物体、触觉观测使用真实摄影风格图像素材。\n\n所有标题、标签、连接箭头、模块框、表格、坐标轴、柱状图、折线图和散点图使用SVG、Canvas或其他可编辑图形元素绘制，不要把文字烘焙进机器人照片。\n\n数据图必须由给定数据生成，不能用装饰性的近似形状代替。\n\n所有缩略图保持合理比例，不拉伸机器人或操作物体。\n模块箭头连接正确，不能穿过文字。\n字体清楚，单词拼写正确，行距舒适。\n\n整体视觉应像一张严谨、清晰、信息密度适中的机器人学习论文综合图，同时保留明确的示意数据声明。", "orientation": "landscape"}, {"id": "web-20260923-154527-ed1b51-1", "case_id": "web-20260923-154527-ed1b51", "title": "Coffee poster", "type": "image", "group": "posters", "src": "assets/cases/web-20260923-154527-ed1b51-1.png", "poster": "assets/cases/web-20260923-154527-ed1b51-1.preview.jpg", "width": 1152, "height": 2048, "duration": null, "prompt": "参考图仅用于观察构图、颜色和形状。请使用代码重新绘制，不得直接或间接使用参考图像素，包括裁剪、缩放、贴图、抠图或作为背景。文字也须重新排版绘制。", "orientation": "portrait"}, {"id": "web-20260924-100935-3f14ec-1", "case_id": "web-20260924-100935-3f14ec", "title": "Star delivery", "type": "video", "group": "videos", "src": "assets/cases/web-20260924-100935-3f14ec-1.mp4", "poster": "assets/cases/web-20260924-100935-3f14ec-1.preview.jpg", "width": 1280, "height": 720, "duration": 10.0, "prompt": "## 《星星快递：点亮书桌城》\n\n一只像素小猫接住闹钟里弹出的星星，乘着键盘列车穿过桌面，沿着书页滑道冲入茶杯制造的激流，最后借助台灯拉绳荡上高空，把星星装进熄灭的灯泡。\n\n**核心动作链：闹钟弹星 → 键盘铁路生长 → 小车加速 → 空格键弹射 → 书页展开 → 茶水决堤 → 纸船冲浪 → 拉绳大回环 → 星光点亮整座桌面。**\n\n### 可直接使用的 Prompt\n\n创作一段充满想象力、具有明确动作推进的纯像素风格动画，横向16:9构图。整个世界必须统一为精细的二维像素画：角色、日常物件、背景、液体、烟雾、光照和粒子全部由清晰可辨的方形像素构成。使用统一的像素尺寸、有限而协调的色板、阶梯状轮廓和少量像素抖色表现层次。不要写实素材，不要手绘线条，不要三维体素，不要把普通视频简单套上马赛克滤镜。\n\n画面是一张夜晚的书桌，以略带俯视的侧面视角呈现完整舞台。左侧摆着一个复古闹钟，前景是一块机械键盘，中间堆着几本厚书，书堆旁边是一只盛着茶水的杯子和一叠便签纸，右侧是一盏没有亮起的台灯。这些物件都保持清楚可辨的日常外形，但全部用像素画绘制。开场安静、结构清晰，物件之间留出足够空间，供后续道路、河流和动作展开。\n\n**第一段：闹钟打开，星星出现。**\n闹钟的两只铃铛突然剧烈跳动，一圈方形声波向外扩散。钟面像机械舱门一样打开，一颗金黄色的像素星星被弹向空中，划出高高的抛物线。一只戴蓝色帽子的白色像素小猫从闹钟底部的小门冲出来，沿钟脚快速攀爬，再纵身跃起，在空中接住星星，落到键盘左端。远处熄灭的台灯里，可以看见一个星形的空插槽，明确暗示小猫需要把星星送到那里。后续镜头始终保持同一只小猫、同一顶帽子和同一颗星星。\n\n**第二段：键盘变成正在生长的铁路。**\n星光照到键盘，沿途按键依次升起，像一排排小楼；方形轨道从按键缝隙里逐段拼装出来，一直向书堆延伸。Enter键抬起，底下长出四只像素车轮，变成小猫的运输车。小猫抱着星星跳上车，小车立即加速，横穿大半个画面，在高低起伏的按键之间急转、下坡，再冲上斜坡。轨道始终在车头前方一段距离快速拼成，让观众看清“道路刚刚出现，小车就冲了过去”的紧张感。小车经过后，车站旗帜和窗户才依次亮起，世界沿着运动路线被逐步激活。\n\n**第三段：空格键弹射，书页展开成滑道。**\n小车冲到键盘末端，压下空格键。空格键像蓄力跳板一样先明显下沉，再猛然回弹，把小车和小猫一起抛向书堆。用清楚的起跳、腾空和落地呈现一次横跨两个物件的大跳跃，而不是瞬间传送。小猫飞行途中，最上方的书突然翻开，书页一张接一张展开，接成一条盘绕书堆的长滑道。小车落上滑道后高速下滑，冲过弯道、跃过短缺口，纸页被车轮带起，在后方翻飞。书依然能被辨认出来，只是书页成为了小世界里的道路。\n\n**第四段：茶水形成激流，便签折成纸船。**\n展开的书封面碰到茶杯把手，茶杯缓缓倾斜，随后倾泻出一股由深浅蓝色像素块组成的水流。水流先冲过书堆底部，再沿桌面向台灯方向奔涌，把原本的陆路切断。浪头由不断重组的阶梯状色块构成，水花则是向外飞散的小方块。小猫抵达滑道尽头时，一张便签被水流卷起，在空中连续折叠成纸船。小猫抱着星星跳进船里，小车留在岸边。纸船立刻被激流推走，绕过杯底，冲下书本之间的小瀑布，再被大浪托起。让船身有明显的俯冲、倾斜和腾空，不能只是在平面上匀速滑动。\n\n**第五段：拉绳荡跃，把星星送进灯里。**\n纸船驶到台灯下方，灯罩里突然垂下一根逐节拼成的像素拉绳。小猫把星星固定在胸前，踩上船头，借浪尖高高跃起，抓住拉绳。拉绳被它的惯性拉成一个大幅摆动的钟摆，小猫从低处荡过，再升到接近画面顶部。到达最高点时，它松开拉绳，沿清晰的弧线飞入灯罩，双手把星星推入灯泡里的星形插槽。保留一个短暂的停顿，再让灯泡突然点亮。\n\n**结尾：整张书桌成为一座亮起的小城。**\n暖黄色光线不是柔焦光晕，而是一圈圈有清晰边缘的像素色带，从台灯向整个桌面扩散。光经过哪里，哪里的世界就完成最后的拼装：键盘小楼亮起窗户，书页滑道旁长出栏杆，茶杯边拼出小码头，便签纸折成几只小鸟飞过灯罩。刚才湍急的河流渐渐平稳，纸船停靠码头。小猫坐在灯罩边缘，晃着双脚，看向被自己点亮的书桌城。\n\n整段动画以连续空间中的行动为主，让观众始终理解角色从哪里出发、经过什么物件、准备到哪里去。镜头保持稳定，必要时只做轻微横向跟随，不依赖快速剪辑或镜头抖动制造动感。**运动高潮来自弹射、滑行、冲浪和荡跃；创意来自多个物件相互触发，而不是无缘无故地换场景。** 所有新结构都通过像素块汇聚、逐格拼装、机械展开或纸张折叠出现，避免整体淡入。保持像素网格稳定，不出现抗锯齿边缘、运动模糊、平滑渐变、写实水流或发光糊边，也不要添加游戏界面、分数、字幕和操作按钮。", "orientation": "landscape"}, {"id": "web-20260924-151128-e1ff7e-1", "case_id": "web-20260924-151128-e1ff7e", "title": "Ceramic study", "type": "image", "group": "painting", "src": "assets/cases/web-20260924-151128-e1ff7e-1.png", "poster": "assets/cases/web-20260924-151128-e1ff7e-1.preview.jpg", "width": 1024, "height": 1024, "duration": null, "prompt": "用当前 libmypaint 笔触绘画后端，绘制一幅 1024×1024 的写实静物画：一只象牙白釉面陶瓷咖啡杯，放在浅灰色哑光桌面上，背景为干净的灰米色。\n\n视角略高于杯口，能看到椭圆形杯口、杯壁厚度和内部空间。杯柄朝右，杯身略微上宽下窄。主体占画面约六成，完整呈现，不加文字、图案或其他物体。\n\n唯一主光来自左上方的大面积柔光。杯身左侧明亮，右侧逐渐转暗；杯底与桌面之间有窄而深的接触阴影，投影向右后方延伸，边缘逐渐柔化。白色陶瓷也必须有清楚的灰阶变化，不能画成一整块白色。釉面高光应柔和克制，保留陶瓷厚实的质感。\n\n优先保证杯口透视、杯壁厚度、杯柄连接和整体体积。不要用黑色轮廓线勾边，不要用随机噪点冒充材质，不要把物体画成矢量图标。\n\n分阶段执行：\n1. 用大笔触建立构图、轮廓和主要明暗，渲染检查。\n2. 修正杯口椭圆、杯柄结构与光影关系，再细化。\n3. 用软笔、局部叠色及必要的同层涂抹建立连续过渡，处理高光、接触阴影和边缘。\n4. 检查全图，以及杯口、杯柄连接和杯底的原生尺寸局部。\n\n只使用真实笔刷绘制，不调用图像生成，不贴入图片。发现结构问题时，删除或重画相关笔触，不用增加纹理掩盖。最终导出 PNG；如果仍有明显插画感，明确标记未达标，不能宣称已经达到照片级写实。", "orientation": "square"}, {"id": "web-20260924-154347-77eef3-1", "case_id": "web-20260924-154347-77eef3", "title": "A bowl of ramen", "type": "image", "group": "painting", "src": "assets/cases/web-20260924-154347-77eef3-1.png", "poster": "assets/cases/web-20260924-154347-77eef3-1.preview.jpg", "width": 1024, "height": 1024, "duration": null, "prompt": "请使用当前 harness 的 paint / libmypaint 后端，绘制一碗具有可信体积、材质和食欲感的日式拉面。\n\n最终交付一张静态 PNG。目标是精细写实的食物绘画：远看结构自然，近看汤汁、陶瓷、面条、叉烧和鸡蛋具有不同质感。不要把“逼真”理解为堆积细线、噪点或大量高光。\n\n一、工作方式与能力边界\n\n1. 使用当前画布规格；以下坐标以 1024×1024 为设计基准，其他尺寸按比例换算。\n2. 使用 plan_creation 建立 paint 路线的计划，所有绘画组件使用 code 路线。\n3. 在空白画布上初始化一次 painting，随后通过 paint_strokes 和图层工具持续修改。不要在中途重新初始化而清空画面。\n4. 只使用当前支持的 round、soft、ink、smudge、eraser。\n5. 不使用外部生成图片、照片贴图、SVG、Canvas 或 3D 渲染结果替代笔触绘画。\n6. 不假设存在选区、剪贴蒙版、Multiply、水彩扩散、自动区域填充或跨图层涂抹。\n7. 曲线需要转换成连续、足够密集的采样点。填色用相互覆盖的笔触完成，不要把多边形顶点列表当成填充命令。\n8. 使用正确的 expected_revision，笔触 ID 保持唯一。每次 paint_strokes 不超过 256 条笔触。\n9. 将工作按可检查的阶段推进。每阶段完成后看实际渲染结果，再决定下一阶段，不能仅根据已提交的参数判断成功。\n\n二、画面构图\n\n画面是一张近距离的食物静物：\n\n- 一只温润的象牙白陶瓷碗。\n- 琥珀色清汤、浅金色面条。\n- 两片形状不同、部分重叠的叉烧。\n- 右上方一半溏心蛋。\n- 少量葱花，集中在食物交汇处。\n- 背景是低对比度的暖灰桌面。\n\n不添加文字、标志、筷子、餐具、复杂背景或额外食物。\n主体约占画面宽度的 70%—75%，四周留出呼吸空间。\n\n采用略俯视的三分之四视角，能同时看见碗内食物和碗身。\n几何参考：\n\n- 碗口外椭圆中心约为 (512, 405)。\n- 外椭圆横向半径约 355，纵向半径约 150。\n- 汤面位于碗口内部，横向半径约 322，纵向半径约 123。\n- 碗身两侧向下收拢，底部约在 y=770。\n- 碗底接触桌面约在 y=790。\n- 投影朝右下延伸。\n\n这些坐标是构图参考，不是僵硬模板。请以预览中的透视协调为准调整。\n尤其注意：碗口、汤面和碗底属于同一个空间，不能像几个互不相关的椭圆叠在一起。\n\n三、统一光线\n\n只有一个主要光源：画面左上方的大面积柔光。\n\n必须保持以下关系：\n\n- 碗身左上较亮，右侧和底部较暗。\n- 碗底接触阴影最深，投影越远越柔和。\n- 食物上的亮部总体朝向左上。\n- 食材接触汤面或互相重叠的位置出现局部暗部。\n- 高光的位置由表面朝向决定，不要给所有物体画一圈白边。\n\n画面最高亮度只留给少量湿润高光和局部陶瓷反光。\n最深暗部只用于狭小的接触缝隙，不用纯黑描出整个主体。\n\n四、色彩与图层\n\n建议色彩起点，可根据实际预览调整：\n\n背景暖灰：#D9D2C6\n陶瓷亮部：#F1EBDD\n陶瓷中间色：#C9C4B8\n陶瓷冷暗部：#858B89\n汤汁金棕：#A96D2C\n汤汁深部：#64462B\n面条浅金：#DEC18A\n面条亮部：#F2DEAF\n叉烧肉色：#B77D68\n叉烧焦边：#754B39\n蛋白暖白：#EEE3CD\n蛋黄橙金：#EAA12D\n葱花深绿：#41673A\n\n不要把颜色机械地当作固定分区。相邻物体之间需要少量颜色反射，例如汤汁使靠近汤面的蛋白和面条带暖色。\n\n按从底到顶的顺序创建图层，建议：\nshadow、bowl、broth、noodles、meat、egg、garnish、accents。\n\n当前图层工具没有重新排序能力，因此创建时就确定遮挡顺序。\n可以返回已有图层继续绘制。\n默认保持图层不透明度为 1，用笔触自身的不透明度控制局部叠色。\n\n五、阶段一：先画一个可信的碗\n\n暂时不画食材纹理。\n\n1. 建立桌面和碗底投影。\n   投影贴近碗底处较窄较深，向右下逐渐变宽、变淡。\n   不要画成均匀的黑色椭圆。\n\n2. 用较大的 round 笔触建立碗身完整轮廓。\n   内部必须覆盖充分，避免出现背景穿透的小孔。\n   靠近轮廓时缩小笔刷，控制边缘。\n\n3. 建立碗口厚度和内壁。\n   碗口是一圈有厚度的陶瓷结构，内外边缘的明暗并不相同。\n   汤面略低于碗沿，保留可见的内壁。\n\n4. 用 soft 和低不透明度的色笔触塑造碗身。\n   亮面、过渡面、暗面必须连贯，避免分成三个明显色带。\n   可在 bowl 图层内使用少量短距离 smudge，不能把整个碗磨成模糊斑块。\n\n5. 碗身反光应宽而克制。\n   不要用一条纯白弧线代替陶瓷体积。\n\n完成后渲染全图检查：\n只看碗和投影，是否已经能理解它的开口、深度、厚度和落地位置？\n如果不能，先修正结构，不进入食材阶段。\n\n六、阶段二：汤汁及水下内容\n\n在 broth 图层建立汤面。\n\n1. 汤不是一块均匀的橙色圆盘。\n   先铺连续的中间色，再根据内壁遮挡、食物投影和光线加入宽缓变化。\n   汤面始终保持一个统一平面，不要画成有中心亮峰的球体。\n\n2. 在汤中画少量被淹没的面条片段。\n   这些片段对比度较低、颜色更接近汤汁、边缘比露出水面的面条更软。\n   画好片段后，在同一图层上用低不透明度汤色局部覆盖，表现水下深度。\n\n3. 不要让每根面条都从头到尾清晰可见。\n   面条应在汤中出现、消失，再在别处露出，形成遮挡和深浅变化。\n\n4. 在靠近碗内壁、面条和叉烧的位置保留局部反光空间。\n   此时只做宽泛光色关系，最后再增加少量细小高光。\n\n5. 若添加油花，只画少量尺度不同、对比度很低的小形状。\n   不使用规则圆点阵列，不铺满画面。\n\n七、阶段三：露出汤面的面条\n\n面条不是随机的黄色线条，而是受到重力、相互挤压并局部浸在汤中的柔软圆柱。\n\n1. 先确定几组主要走向：\n   一组从画面左中部弯向中心；\n   一组在前方形成松散弧线；\n   少量短段从叉烧和鸡蛋下方露出。\n   避免每一根都形成完整闭合圈。\n\n2. 先用中暗色建立面条厚度，再用稍窄的浅色笔触塑造朝向光源的一侧。\n   高光偏向左上，不要始终位于线条正中央。\n\n3. 1024 像素画布上，主要面条宽度约 5—12 像素。\n   随距离和遮挡变化调整宽度，不要所有面条完全一样粗。\n\n4. 在交叉位置明确上下关系：\n   上面的面条保持连续；\n   下面的面条局部中断；\n   接触处增加很小的暖暗影。\n\n5. 表面亮部需要断续变化。\n   不能每根面条都有同样长度、同样亮度的白色描边。\n\n6. 先把少数主面条画对，再增加次要片段。\n   宁可有疏密和遮挡，也不要用大量平行曲线填满汤面。\n\n八、阶段四：叉烧与溏心蛋\n\n叉烧放在偏左后方，两片部分重叠；蛋放在右上区域。\n它们需要位于汤面内，并与面条产生明确遮挡。\n\n叉烧：\n- 先建立不完全规则的外轮廓和薄片厚度。\n- 焦边比内部深，但不形成均匀黑边。\n- 瘦肉使用低饱和红棕色；脂肪偏暖灰白。\n- 肌理沿肉片结构变化，只在局部出现。\n- 不画成规则同心圆或整齐的大理石纹。\n- 用宽缓明暗表现轻微弯曲，用接触阴影说明浸汤位置。\n- 最后加几处短小湿润亮点，不能整片像塑料一样发光。\n\n溏心蛋：\n- 蛋白切面为略不规则的透视椭圆。\n- 外缘与切面之间有厚度，不能只有一个白色椭圆套黄色圆。\n- 蛋白亮部暖白，背光部偏灰，并带少量汤色反射。\n- 蛋黄的位置和形状不必完全居中、完全规则。\n- 蛋黄颜色在金黄、橙黄和较深橙色之间柔和变化。\n- 用少量局部高光表现湿润，不画白色环形边框。\n- 蛋的下缘被汤和少量面条遮挡，加入窄小接触暗部，避免悬浮。\n\n完成后渲染并检查食材区域：\n叉烧是否像有厚度的肉片？\n鸡蛋是否有切面、体积和水分？\n两者是否真正位于碗内，而不是贴在画面上的图标？\n\n九、阶段五：葱花、边缘与最终高光\n\n1. 葱花只在局部形成疏密变化。\n   使用深绿外侧、浅绿内侧，形状包含斜切短段和不完整小环。\n   不要每片葱花大小相同、角度相同。\n   不要把葱花作为掩盖面条结构问题的碎点。\n\n2. 在 accents 图层添加少量最终反光：\n   - 碗口左上局部的陶瓷亮边；\n   - 食材和汤接触位置的短小反光；\n   - 蛋黄和叉烧表面的几个湿润亮点；\n   - 极少数面条的亮部强调。\n\n3. 亮边必须有中断和强弱变化。\n   不要完整描出汤面轮廓，不要给所有食物统一描边。\n\n4. 根据深度安排边缘：\n   - 前方碗沿和焦点附近的食材相对清晰；\n   - 水下内容较柔；\n   - 背景与远处投影柔和。\n   不要整张画全部锐利，也不要最后全局涂抹。\n\n十、笔触控制\n\n- 大面积铺色：约 40—120 像素，内部相互覆盖，边缘改用小笔刷。\n- 中等体积塑造：约 12—40 像素。\n- 面条和局部结构：约 3—12 像素。\n- 最终微小高光：约 1—3 像素。\n\n这些尺寸是起点，按实际画面调整。\n\n大形底色要覆盖充分；柔和过渡可从 0.08—0.25 的笔触不透明度开始。\n不要反复低透明度叠色到颜色发脏。\n\n曲线采样应足够密集，避免显露一串分离圆点。\n适当改变压力，但不要把所有线条末端都收成尖刺。\n\nsmudge 仅用于当前图层已有颜色的短距离融合。\neraser 仅用于清理当前图层，不把擦除当作白色颜料。\nink 仅用于少量精确暗缝或细节，不用于描出所有物体。\n\n十一、检查、修正和交付\n\n至少在以下节点检查实际渲染：\nA. 碗与投影完成后；\nB. 汤和主要面条完成后；\nC. 叉烧、鸡蛋完成后；\nD. 最终高光完成后。\n\n全图检查构图、透视、光线和材料分离；\n使用 inspect_region 检查碗沿、面条交叉处、蛋与汤接触处等关键区域。\n\n优先按这个顺序修正：\n1. 碗的透视与汤面位置；\n2. 食物的体积及遮挡；\n3. 光源一致性和接触阴影；\n4. 不同材料的边缘与反光；\n5. 最后才是微小纹理。\n\n不要通过增加噪点修复体积错误。\n不要通过增加高光修复不成立的明暗。\n不要为了填满空白增加无意义食材。\n\n对关键修改保存版本，必要时 compare_versions。\n如果新版更杂乱、更平、更像卡通，返回较好的版本，只修正明确问题。\n\n最终验收：\n- 碗口椭圆、碗身与底部透视协调；\n- 汤面低于碗沿，没有溢出；\n- 面条有厚度、遮挡和浸汤变化；\n- 叉烧、蛋白、蛋黄、汤汁、陶瓷可以凭质感区分；\n- 食材没有漂浮或贴纸感；\n- 高光符合统一光源，数量克制；\n- 没有明显笔触圆点串、规则重复纹理和大面积漏底；\n- 缩小看整体仍然可信，局部细节没有破坏大形。\n\n基于真实预览记录 review，然后导出 PNG。\n如果仍有明显问题且还有执行预算，继续修正最重要的问题。\n若预算结束仍未达标，交付当前最佳草稿并如实说明不足，不宣称达到照片级写实。", "orientation": "square"}, {"id": "web-20260924-164257-a2d8ed-1", "case_id": "web-20260924-164257-a2d8ed", "title": "Morning still life · output 1", "type": "image", "group": "painting", "src": "assets/cases/web-20260924-164257-a2d8ed-1.png", "poster": "assets/cases/web-20260924-164257-a2d8ed-1.preview.jpg", "width": 768, "height": 768, "duration": null, "prompt": "请使用 pathtrace 后端，创作一张具有真实商业摄影质感的“清晨咖啡与早餐”静物图，输出正方形静态 PNG。\n\n重点是可信的几何、材质、光照和空间关系。画面精细但克制，不要用大量小物件掩盖主要结构问题。\n\n一、构图与主体\n\n采用略俯视的三分之四视角，能看见杯口、盘面和玻璃杯中的液面。主体集中在画面中下部，占画面约 75%，上方保留适量背景。\n\n桌面为浅色橡木，木纹柔和、尺度自然，避免高对比度条纹抢夺主体。\n\n安排以下物体：\n\n1. 左后方：一只奶油白陶瓷咖啡杯\n- 杯身略向底部收拢，杯口圆润。\n- 必须具有内壁、外壁、杯底和合理厚度。\n- 右侧有一个弯曲杯柄，通过曲线管道构造，上下两端自然连接杯身。\n- 杯柄中心留出真实空洞，不能像贴在杯外的实心圆环。\n- 杯内是深棕色黑咖啡，液面略低于杯沿，保留可见的内壁。\n- 不添加拉花、奶泡或蒸汽。\n\n2. 咖啡杯下方：一只配套陶瓷碟\n- 碟子中央较低，边缘轻微抬起。\n- 有真实厚度，边缘圆润，不能用一张无厚度平面替代。\n- 咖啡杯稳稳放在碟子中央，底部与碟面接触。\n- 碟子与杯子使用同一色系，但反光随朝向变化。\n\n3. 右后方：一只装有清水的透明玻璃杯\n- 杯身近似圆柱，但杯口略宽于底部。\n- 杯壁薄，杯底略厚，杯沿圆润。\n- 水位约为杯高的 60%。\n- 玻璃具有内外表面；水为独立的封闭体积。\n- 水体贴近内壁，避免与玻璃表面完全重合，也不要留出肉眼明显的空气缝。\n- 通过折射、杯底厚度和液面反光表现玻璃与水，不能只靠透明度降低来模拟。\n- 不添加气泡或飞溅。\n\n4. 前方偏右：一只低矮浅盘，盛放两块黄油饼干\n- 盘子为低饱和灰蓝色陶瓷，边缘有轻微起伏。\n- 两块饼干部分重叠，下面一块保持平放，上面一块自然搭在其上。\n- 饼干为厚实的圆角长方形，尺寸和朝向略有差异。\n- 表面是低光泽的烘焙金黄色，边缘稍深。\n- 每块只有少量浅凹的小孔或压痕，排列不必完全规则。\n- 用有限的细节表达烘焙质感，不要画成金属块、塑料块或布满黑点的海绵。\n- 这部分优先保证厚度、轮廓和接触关系，再处理细节。\n\n5. 前方偏左：一把不锈钢咖啡勺\n- 勺头是有深度的浅凹椭圆形，具有内外表面和薄边缘。\n- 手柄细长，边缘圆润，与勺头自然连接。\n- 不要用一个实心椭球代替勺头。\n- 勺子斜放在桌面上，与盘子保持少量间距。\n- 根据自身弯曲形状建立合理支撑点，不要强行让整个勺子底面都贴住桌面。\n- 金属具有清楚但不过度锐利的环境反射。\n\n主体之间形成自然的前后遮挡，但不要遮住杯柄、水位线或勺头这些关键结构。\n\n二、光线与摄影效果\n\n主光来自画面左上方，使用一块较大的矩形柔光源。\n环境补光较弱，整体明亮温暖，暗部仍保留细节。\n\n要求：\n- 所有投影和高光符合统一的光照方向。\n- 接触处有窄而明确的阴影，离开接触处后逐渐柔和。\n- 杯内、杯柄内侧、饼干重叠处、勺头凹面都有可信的明暗变化。\n- 陶瓷呈现宽缓反光；金属反射更清晰；玻璃主要通过边缘、折射和局部反光体现形状。\n- 白色陶瓷不能过曝，透明玻璃不能变成黑色实体。\n- 不刻意追求强烈焦散，不用白色线条手工描出高光轮廓。\n- 全部主体保持清晰，不使用模糊效果掩盖建模问题。\n- 背景简洁，不添加窗户模型、文字、品牌、餐巾或额外装饰。\n\n三、几何与材质策略\n\n使用当前支持的结构化场景工具完成。\n\n- 杯、碟、盘、玻璃容器：优先使用带完整截面的旋转体。\n- 杯柄：使用曲线管道，注意端点与杯身的连接。\n- 饼干：使用圆角几何或自定义网格，避免机械锐边。\n- 勺头：使用自定义网格建立浅凹曲面与厚度；手柄可用圆角几何或曲线结构。\n- 液体：使用独立封闭几何，保持液面水平。\n\n陶瓷、金属、玻璃、水、木材和饼干必须具有不同的反光特征。\n材质预设只是起点，需要结合实际预览调整颜色、粗糙度、透射和折射率。\n\n不调用图片生成 API。\n不把完整照片贴到平面上替代建模。\n不假设存在尚未接入的流体模拟、布料模拟、体积蒸汽或食物次表面散射功能。\n\n四、分阶段执行\n\n阶段 A：构图与支撑关系\n先建立全部主体的大形，使用快速预览。\n检查物体比例、相机角度、留白和遮挡。\n逐项检查物体是否落地、是否互相穿插，以及杯子是否真正坐在碟子上。\n\n阶段 B：容器与曲面结构\n完善杯壁、杯柄、碟沿、玻璃杯底、液面和勺头凹面。\n从预览中确认这些结构能够被看见，不只是存在于场景参数中。\n\n阶段 C：材质与光线\n切换到路径追踪预览，建议 preview_samples 为 32。\n先区分陶瓷、金属、玻璃和液体，再调整木桌与饼干。\n如果出现异常黑色、过曝或塑料感，优先检查几何、法线、材质和照明。\n\n阶段 D：局部细节\n在主体已经成立后，增加饼干压痕、边缘色差和适量木纹。\n细节尺度应符合真实物体，不要均匀撒噪点。\n保留干净的大面积明暗，避免整个画面都变得粗糙。\n\n阶段 E：成品输出\n将 final_samples 设为 512，bounces 设为 10。\n导出后观察实际成品，不用预览代替成品评审。\n若仍有明显噪点，先判断是否集中于复杂透射区域，再决定是否提高采样；不要无依据反复重渲染。\n\n五、验收重点\n\n至少检查以下局部：\n- 咖啡杯口：能看到壁厚、内壁和低于杯沿的咖啡液面。\n- 杯柄连接：上下连接自然，没有明显穿插或悬空。\n- 玻璃杯：杯壁、杯底、水位线和透过杯体的背景关系可信。\n- 饼干重叠处：上下关系清楚，有接触阴影，不像悬浮的两块板。\n- 勺头：凹面可辨认，具有厚度和符合曲面的反射。\n- 桌面接触处：杯碟、盘子、玻璃杯和勺子各自具有合理支撑和阴影。\n\n修正顺序：\n结构与支撑关系 → 透视与遮挡 → 材质与光线 → 局部细节 → 采样噪点。\n\n最终画面应该让人感受到这些物体真实地摆放在同一张桌面上。\n如饼干等复杂材质仍有局限，请如实说明，不要仅因为渲染完成就宣称达到照片级效果。", "orientation": "square"}, {"id": "web-20260924-164257-a2d8ed-2", "case_id": "web-20260924-164257-a2d8ed", "title": "Morning still life · output 2", "type": "image", "group": "painting", "src": "assets/cases/web-20260924-164257-a2d8ed-2.png", "poster": "assets/cases/web-20260924-164257-a2d8ed-2.preview.jpg", "width": 768, "height": 768, "duration": null, "prompt": "请使用 pathtrace 后端，创作一张具有真实商业摄影质感的“清晨咖啡与早餐”静物图，输出正方形静态 PNG。\n\n重点是可信的几何、材质、光照和空间关系。画面精细但克制，不要用大量小物件掩盖主要结构问题。\n\n一、构图与主体\n\n采用略俯视的三分之四视角，能看见杯口、盘面和玻璃杯中的液面。主体集中在画面中下部，占画面约 75%，上方保留适量背景。\n\n桌面为浅色橡木，木纹柔和、尺度自然，避免高对比度条纹抢夺主体。\n\n安排以下物体：\n\n1. 左后方：一只奶油白陶瓷咖啡杯\n- 杯身略向底部收拢，杯口圆润。\n- 必须具有内壁、外壁、杯底和合理厚度。\n- 右侧有一个弯曲杯柄，通过曲线管道构造，上下两端自然连接杯身。\n- 杯柄中心留出真实空洞，不能像贴在杯外的实心圆环。\n- 杯内是深棕色黑咖啡，液面略低于杯沿，保留可见的内壁。\n- 不添加拉花、奶泡或蒸汽。\n\n2. 咖啡杯下方：一只配套陶瓷碟\n- 碟子中央较低，边缘轻微抬起。\n- 有真实厚度，边缘圆润，不能用一张无厚度平面替代。\n- 咖啡杯稳稳放在碟子中央，底部与碟面接触。\n- 碟子与杯子使用同一色系，但反光随朝向变化。\n\n3. 右后方：一只装有清水的透明玻璃杯\n- 杯身近似圆柱，但杯口略宽于底部。\n- 杯壁薄，杯底略厚，杯沿圆润。\n- 水位约为杯高的 60%。\n- 玻璃具有内外表面；水为独立的封闭体积。\n- 水体贴近内壁，避免与玻璃表面完全重合，也不要留出肉眼明显的空气缝。\n- 通过折射、杯底厚度和液面反光表现玻璃与水，不能只靠透明度降低来模拟。\n- 不添加气泡或飞溅。\n\n4. 前方偏右：一只低矮浅盘，盛放两块黄油饼干\n- 盘子为低饱和灰蓝色陶瓷，边缘有轻微起伏。\n- 两块饼干部分重叠，下面一块保持平放，上面一块自然搭在其上。\n- 饼干为厚实的圆角长方形，尺寸和朝向略有差异。\n- 表面是低光泽的烘焙金黄色，边缘稍深。\n- 每块只有少量浅凹的小孔或压痕，排列不必完全规则。\n- 用有限的细节表达烘焙质感，不要画成金属块、塑料块或布满黑点的海绵。\n- 这部分优先保证厚度、轮廓和接触关系，再处理细节。\n\n5. 前方偏左：一把不锈钢咖啡勺\n- 勺头是有深度的浅凹椭圆形，具有内外表面和薄边缘。\n- 手柄细长，边缘圆润，与勺头自然连接。\n- 不要用一个实心椭球代替勺头。\n- 勺子斜放在桌面上，与盘子保持少量间距。\n- 根据自身弯曲形状建立合理支撑点，不要强行让整个勺子底面都贴住桌面。\n- 金属具有清楚但不过度锐利的环境反射。\n\n主体之间形成自然的前后遮挡，但不要遮住杯柄、水位线或勺头这些关键结构。\n\n二、光线与摄影效果\n\n主光来自画面左上方，使用一块较大的矩形柔光源。\n环境补光较弱，整体明亮温暖，暗部仍保留细节。\n\n要求：\n- 所有投影和高光符合统一的光照方向。\n- 接触处有窄而明确的阴影，离开接触处后逐渐柔和。\n- 杯内、杯柄内侧、饼干重叠处、勺头凹面都有可信的明暗变化。\n- 陶瓷呈现宽缓反光；金属反射更清晰；玻璃主要通过边缘、折射和局部反光体现形状。\n- 白色陶瓷不能过曝，透明玻璃不能变成黑色实体。\n- 不刻意追求强烈焦散，不用白色线条手工描出高光轮廓。\n- 全部主体保持清晰，不使用模糊效果掩盖建模问题。\n- 背景简洁，不添加窗户模型、文字、品牌、餐巾或额外装饰。\n\n三、几何与材质策略\n\n使用当前支持的结构化场景工具完成。\n\n- 杯、碟、盘、玻璃容器：优先使用带完整截面的旋转体。\n- 杯柄：使用曲线管道，注意端点与杯身的连接。\n- 饼干：使用圆角几何或自定义网格，避免机械锐边。\n- 勺头：使用自定义网格建立浅凹曲面与厚度；手柄可用圆角几何或曲线结构。\n- 液体：使用独立封闭几何，保持液面水平。\n\n陶瓷、金属、玻璃、水、木材和饼干必须具有不同的反光特征。\n材质预设只是起点，需要结合实际预览调整颜色、粗糙度、透射和折射率。\n\n不调用图片生成 API。\n不把完整照片贴到平面上替代建模。\n不假设存在尚未接入的流体模拟、布料模拟、体积蒸汽或食物次表面散射功能。\n\n四、分阶段执行\n\n阶段 A：构图与支撑关系\n先建立全部主体的大形，使用快速预览。\n检查物体比例、相机角度、留白和遮挡。\n逐项检查物体是否落地、是否互相穿插，以及杯子是否真正坐在碟子上。\n\n阶段 B：容器与曲面结构\n完善杯壁、杯柄、碟沿、玻璃杯底、液面和勺头凹面。\n从预览中确认这些结构能够被看见，不只是存在于场景参数中。\n\n阶段 C：材质与光线\n切换到路径追踪预览，建议 preview_samples 为 32。\n先区分陶瓷、金属、玻璃和液体，再调整木桌与饼干。\n如果出现异常黑色、过曝或塑料感，优先检查几何、法线、材质和照明。\n\n阶段 D：局部细节\n在主体已经成立后，增加饼干压痕、边缘色差和适量木纹。\n细节尺度应符合真实物体，不要均匀撒噪点。\n保留干净的大面积明暗，避免整个画面都变得粗糙。\n\n阶段 E：成品输出\n将 final_samples 设为 512，bounces 设为 10。\n导出后观察实际成品，不用预览代替成品评审。\n若仍有明显噪点，先判断是否集中于复杂透射区域，再决定是否提高采样；不要无依据反复重渲染。\n\n五、验收重点\n\n至少检查以下局部：\n- 咖啡杯口：能看到壁厚、内壁和低于杯沿的咖啡液面。\n- 杯柄连接：上下连接自然，没有明显穿插或悬空。\n- 玻璃杯：杯壁、杯底、水位线和透过杯体的背景关系可信。\n- 饼干重叠处：上下关系清楚，有接触阴影，不像悬浮的两块板。\n- 勺头：凹面可辨认，具有厚度和符合曲面的反射。\n- 桌面接触处：杯碟、盘子、玻璃杯和勺子各自具有合理支撑和阴影。\n\n修正顺序：\n结构与支撑关系 → 透视与遮挡 → 材质与光线 → 局部细节 → 采样噪点。\n\n最终画面应该让人感受到这些物体真实地摆放在同一张桌面上。\n如饼干等复杂材质仍有局限，请如实说明，不要仅因为渲染完成就宣称达到照片级效果。", "orientation": "square"}, {"id": "web-20260924-164257-a2d8ed-3", "case_id": "web-20260924-164257-a2d8ed", "title": "Morning still life · output 3", "type": "image", "group": "painting", "src": "assets/cases/web-20260924-164257-a2d8ed-3.png", "poster": "assets/cases/web-20260924-164257-a2d8ed-3.preview.jpg", "width": 768, "height": 768, "duration": null, "prompt": "请使用 pathtrace 后端，创作一张具有真实商业摄影质感的“清晨咖啡与早餐”静物图，输出正方形静态 PNG。\n\n重点是可信的几何、材质、光照和空间关系。画面精细但克制，不要用大量小物件掩盖主要结构问题。\n\n一、构图与主体\n\n采用略俯视的三分之四视角，能看见杯口、盘面和玻璃杯中的液面。主体集中在画面中下部，占画面约 75%，上方保留适量背景。\n\n桌面为浅色橡木，木纹柔和、尺度自然，避免高对比度条纹抢夺主体。\n\n安排以下物体：\n\n1. 左后方：一只奶油白陶瓷咖啡杯\n- 杯身略向底部收拢，杯口圆润。\n- 必须具有内壁、外壁、杯底和合理厚度。\n- 右侧有一个弯曲杯柄，通过曲线管道构造，上下两端自然连接杯身。\n- 杯柄中心留出真实空洞，不能像贴在杯外的实心圆环。\n- 杯内是深棕色黑咖啡，液面略低于杯沿，保留可见的内壁。\n- 不添加拉花、奶泡或蒸汽。\n\n2. 咖啡杯下方：一只配套陶瓷碟\n- 碟子中央较低，边缘轻微抬起。\n- 有真实厚度，边缘圆润，不能用一张无厚度平面替代。\n- 咖啡杯稳稳放在碟子中央，底部与碟面接触。\n- 碟子与杯子使用同一色系，但反光随朝向变化。\n\n3. 右后方：一只装有清水的透明玻璃杯\n- 杯身近似圆柱，但杯口略宽于底部。\n- 杯壁薄，杯底略厚，杯沿圆润。\n- 水位约为杯高的 60%。\n- 玻璃具有内外表面；水为独立的封闭体积。\n- 水体贴近内壁，避免与玻璃表面完全重合，也不要留出肉眼明显的空气缝。\n- 通过折射、杯底厚度和液面反光表现玻璃与水，不能只靠透明度降低来模拟。\n- 不添加气泡或飞溅。\n\n4. 前方偏右：一只低矮浅盘，盛放两块黄油饼干\n- 盘子为低饱和灰蓝色陶瓷，边缘有轻微起伏。\n- 两块饼干部分重叠，下面一块保持平放，上面一块自然搭在其上。\n- 饼干为厚实的圆角长方形，尺寸和朝向略有差异。\n- 表面是低光泽的烘焙金黄色，边缘稍深。\n- 每块只有少量浅凹的小孔或压痕，排列不必完全规则。\n- 用有限的细节表达烘焙质感，不要画成金属块、塑料块或布满黑点的海绵。\n- 这部分优先保证厚度、轮廓和接触关系，再处理细节。\n\n5. 前方偏左：一把不锈钢咖啡勺\n- 勺头是有深度的浅凹椭圆形，具有内外表面和薄边缘。\n- 手柄细长，边缘圆润，与勺头自然连接。\n- 不要用一个实心椭球代替勺头。\n- 勺子斜放在桌面上，与盘子保持少量间距。\n- 根据自身弯曲形状建立合理支撑点，不要强行让整个勺子底面都贴住桌面。\n- 金属具有清楚但不过度锐利的环境反射。\n\n主体之间形成自然的前后遮挡，但不要遮住杯柄、水位线或勺头这些关键结构。\n\n二、光线与摄影效果\n\n主光来自画面左上方，使用一块较大的矩形柔光源。\n环境补光较弱，整体明亮温暖，暗部仍保留细节。\n\n要求：\n- 所有投影和高光符合统一的光照方向。\n- 接触处有窄而明确的阴影，离开接触处后逐渐柔和。\n- 杯内、杯柄内侧、饼干重叠处、勺头凹面都有可信的明暗变化。\n- 陶瓷呈现宽缓反光；金属反射更清晰；玻璃主要通过边缘、折射和局部反光体现形状。\n- 白色陶瓷不能过曝，透明玻璃不能变成黑色实体。\n- 不刻意追求强烈焦散，不用白色线条手工描出高光轮廓。\n- 全部主体保持清晰，不使用模糊效果掩盖建模问题。\n- 背景简洁，不添加窗户模型、文字、品牌、餐巾或额外装饰。\n\n三、几何与材质策略\n\n使用当前支持的结构化场景工具完成。\n\n- 杯、碟、盘、玻璃容器：优先使用带完整截面的旋转体。\n- 杯柄：使用曲线管道，注意端点与杯身的连接。\n- 饼干：使用圆角几何或自定义网格，避免机械锐边。\n- 勺头：使用自定义网格建立浅凹曲面与厚度；手柄可用圆角几何或曲线结构。\n- 液体：使用独立封闭几何，保持液面水平。\n\n陶瓷、金属、玻璃、水、木材和饼干必须具有不同的反光特征。\n材质预设只是起点，需要结合实际预览调整颜色、粗糙度、透射和折射率。\n\n不调用图片生成 API。\n不把完整照片贴到平面上替代建模。\n不假设存在尚未接入的流体模拟、布料模拟、体积蒸汽或食物次表面散射功能。\n\n四、分阶段执行\n\n阶段 A：构图与支撑关系\n先建立全部主体的大形，使用快速预览。\n检查物体比例、相机角度、留白和遮挡。\n逐项检查物体是否落地、是否互相穿插，以及杯子是否真正坐在碟子上。\n\n阶段 B：容器与曲面结构\n完善杯壁、杯柄、碟沿、玻璃杯底、液面和勺头凹面。\n从预览中确认这些结构能够被看见，不只是存在于场景参数中。\n\n阶段 C：材质与光线\n切换到路径追踪预览，建议 preview_samples 为 32。\n先区分陶瓷、金属、玻璃和液体，再调整木桌与饼干。\n如果出现异常黑色、过曝或塑料感，优先检查几何、法线、材质和照明。\n\n阶段 D：局部细节\n在主体已经成立后，增加饼干压痕、边缘色差和适量木纹。\n细节尺度应符合真实物体，不要均匀撒噪点。\n保留干净的大面积明暗，避免整个画面都变得粗糙。\n\n阶段 E：成品输出\n将 final_samples 设为 512，bounces 设为 10。\n导出后观察实际成品，不用预览代替成品评审。\n若仍有明显噪点，先判断是否集中于复杂透射区域，再决定是否提高采样；不要无依据反复重渲染。\n\n五、验收重点\n\n至少检查以下局部：\n- 咖啡杯口：能看到壁厚、内壁和低于杯沿的咖啡液面。\n- 杯柄连接：上下连接自然，没有明显穿插或悬空。\n- 玻璃杯：杯壁、杯底、水位线和透过杯体的背景关系可信。\n- 饼干重叠处：上下关系清楚，有接触阴影，不像悬浮的两块板。\n- 勺头：凹面可辨认，具有厚度和符合曲面的反射。\n- 桌面接触处：杯碟、盘子、玻璃杯和勺子各自具有合理支撑和阴影。\n\n修正顺序：\n结构与支撑关系 → 透视与遮挡 → 材质与光线 → 局部细节 → 采样噪点。\n\n最终画面应该让人感受到这些物体真实地摆放在同一张桌面上。\n如饼干等复杂材质仍有局限，请如实说明，不要仅因为渲染完成就宣称达到照片级效果。", "orientation": "square"}, {"id": "web-20260924-171756-98f1b3-1", "case_id": "web-20260924-171756-98f1b3", "title": "Breakfast delivery", "type": "video", "group": "videos", "src": "assets/cases/web-20260924-171756-98f1b3-1.mp4", "poster": "assets/cases/web-20260924-171756-98f1b3-1.preview.jpg", "width": 1280, "height": 720, "duration": 10.0, "prompt": "Create a ~10-second short video telling a “final breakfast delivery” story. All elements in the scene — characters, buildings, streets, bridges, platforms, vehicles, obstacles, and props — must be represented in one unified abstract form. Do not include any explicit description of surface appearance, texture, facial details, clothing, or decorative styling. Focus on narrative, motion, spatial relationships, timing, and camera choreography.\n\nThe story begins in a quiet town square. A small protagonist receives a delivery mission and catches a small item. It immediately starts moving, passes through narrow streets, avoids moving obstacles, and is briefly watched by nearby bystanders. It reaches a broken bridge, where a helper on the far side pushes a temporary connector into place. The protagonist crosses just before it retracts. Then it enters a vertical area where rising platforms lift it upward in sequence. One platform is too slow, so the protagonist changes route using a side structure and continues climbing. Near the end, the carried item slips away, but another small character appears and redirects it, allowing the protagonist to catch it and continue. At the top, the item is delivered to a waiting figure. The delivery triggers a chain reaction in the surrounding area and then across the town below. Finally, the camera rapidly retraces the whole path back to the original square, where the starting window opens again and a new mission begins, creating a perfect loop.", "orientation": "landscape"}, {"id": "web-20260927-151424-8fd339-1", "case_id": "web-20260927-151424-8fd339", "title": "Mountain lake", "type": "image", "group": "illustrations", "src": "assets/cases/web-20260927-151424-8fd339-1.png", "poster": "assets/cases/web-20260927-151424-8fd339-1.preview.jpg", "width": 2048, "height": 1152, "duration": null, "prompt": "Create a beautiful landscape illustration with a strong sense of depth and a calm, poetic atmosphere. The scene shows a tranquil mountain lake at sunrise.\nIn the foreground, place a gently curved grassy shore with scattered wildflowers, a few smooth rocks, and a small wooden boat resting near the water’s edge. Add several reeds growing beside the lake, leaning slightly in the breeze. The grass, flowers, rocks, and wooden boat should all have visible surface detail and texture, rendered with delicate brushstrokes to evoke the richness of a real natural scene.\nIn the middle ground, depict a wide reflective lake with subtle ripples. Near the center-left, include a small wooden dock extending into the water. A few lotus leaves or floating plants can be placed near the shore for visual richness. The lake should mirror the sky and mountains with soft reflections, while the water surface should show fine variations in tone and texture, giving it a realistic and gently layered appearance.\nIn the background, create layered rolling hills and tall mountains, with the farthest mountains partially softened by light mist. Place a small traditional pavilion or house near the foot of the mountain on one side, partially surrounded by trees, to give the scene a story-like feeling. The mountains, trees, and architecture should be rendered with refined detail and subtle natural textures, so that the scene feels believable and immersive.\nThe sky should show a warm sunrise gradient, transitioning from pale golden light near the horizon to soft blue higher up. Add a few thin clouds catching the morning light. Let sunlight spread diagonally across the scene, illuminating the lake surface and the tops of the grass and trees. Do not use Image Generation Model or API.", "orientation": "landscape"}];